using ExrMetadataMap = std::map<std::string, std::string>;

bool graphPreviewDebugEnabled() {
    static const bool enabled = std::getenv("HDRSPACE_DEBUG_GRAPH_PREVIEW") != nullptr;
    return enabled;
}

void graphPreviewDebugLog(const std::string& message) {
    if (!graphPreviewDebugEnabled()) {
        return;
    }

    static std::mutex mutex;
    std::lock_guard<std::mutex> lock(mutex);
    std::ofstream output("/tmp/hdrspace_graph_preview.log", std::ios::app);
    if (!output) {
        return;
    }

    const auto now = std::chrono::system_clock::now();
    const auto time = std::chrono::system_clock::to_time_t(now);
    output << std::put_time(std::localtime(&time), "%H:%M:%S") << " | " << message << "\n";
}

void writeNativeOpenExr(const std::string& filename, size_t width, size_t height, int channels, float* data, const ExrMetadataMap& metadata, bool writeHalf) {
    Imf::setGlobalThreadCount(static_cast<int>(std::max(1u, std::thread::hardware_concurrency())));

    Imf::Header header(static_cast<int>(width), static_cast<int>(height));
    for (const auto& [key, value] : metadata) {
        header.insert(key.c_str(), Imf::StringAttribute(value.c_str()));
    }

    Imf::ChannelList& channelList = header.channels();
    if (channels == 3) {
        if (writeHalf) {
            channelList.insert("R", Imf::Channel(Imf::HALF));
            channelList.insert("G", Imf::Channel(Imf::HALF));
            channelList.insert("B", Imf::Channel(Imf::HALF));

            std::vector<half> buffer(width * height * 3);
            for (size_t i = 0; i < width * height * 3; ++i) {
                buffer[i] = data[i];
            }

            Imf::FrameBuffer frameBuffer;
            frameBuffer.insert("R", Imf::Slice(Imf::HALF, reinterpret_cast<char*>(buffer.data()), 6, static_cast<size_t>(6 * width)));
            frameBuffer.insert("G", Imf::Slice(Imf::HALF, reinterpret_cast<char*>(buffer.data()) + 2, 6, static_cast<size_t>(6 * width)));
            frameBuffer.insert("B", Imf::Slice(Imf::HALF, reinterpret_cast<char*>(buffer.data()) + 4, 6, static_cast<size_t>(6 * width)));

            Imf::OutputFile file(filename.c_str(), header);
            file.setFrameBuffer(frameBuffer);
            file.writePixels(static_cast<int>(height));
            return;
        }

        channelList.insert("R", Imf::Channel(Imf::FLOAT));
        channelList.insert("G", Imf::Channel(Imf::FLOAT));
        channelList.insert("B", Imf::Channel(Imf::FLOAT));
        Imf::FrameBuffer frameBuffer;
        frameBuffer.insert("R", Imf::Slice(Imf::FLOAT, reinterpret_cast<char*>(data), 12, static_cast<size_t>(12 * width)));
        frameBuffer.insert("G", Imf::Slice(Imf::FLOAT, reinterpret_cast<char*>(data) + 4, 12, static_cast<size_t>(12 * width)));
        frameBuffer.insert("B", Imf::Slice(Imf::FLOAT, reinterpret_cast<char*>(data) + 8, 12, static_cast<size_t>(12 * width)));
        Imf::OutputFile file(filename.c_str(), header);
        file.setFrameBuffer(frameBuffer);
        file.writePixels(static_cast<int>(height));
        return;
    }

    if (channels == 1) {
        if (writeHalf) {
            channelList.insert("Y", Imf::Channel(Imf::HALF));

            std::vector<half> buffer(width * height);
            for (size_t i = 0; i < width * height; ++i) {
                buffer[i] = data[i];
            }

            Imf::FrameBuffer frameBuffer;
            frameBuffer.insert("Y", Imf::Slice(Imf::HALF, reinterpret_cast<char*>(buffer.data()), 2, static_cast<size_t>(2 * width)));
            Imf::OutputFile file(filename.c_str(), header);
            file.setFrameBuffer(frameBuffer);
            file.writePixels(static_cast<int>(height));
            return;
        }

        channelList.insert("Y", Imf::Channel(Imf::FLOAT));
        Imf::FrameBuffer frameBuffer;
        frameBuffer.insert("Y", Imf::Slice(Imf::FLOAT, reinterpret_cast<char*>(data), 4, static_cast<size_t>(4 * width)));
        Imf::OutputFile file(filename.c_str(), header);
        file.setFrameBuffer(frameBuffer);
        file.writePixels(static_cast<int>(height));
        return;
    }

    throw std::runtime_error("Native OpenEXR export only supports 1 or 3 channels.");
}

fs::path hdrspaceExecutablePath() {
    std::vector<char> buffer(4096, '\0');
    uint32_t size = static_cast<uint32_t>(buffer.size());
    if (_NSGetExecutablePath(buffer.data(), &size) != 0) {
        buffer.resize(size + 1, '\0');
        if (_NSGetExecutablePath(buffer.data(), &size) != 0) {
            return {};
        }
    }
    std::error_code ec;
    return fs::weakly_canonical(fs::path(buffer.data()), ec);
}

fs::path hdrspaceBrandingResourcePath(std::string_view fileName) {
    const fs::path exe = hdrspaceExecutablePath();
    std::error_code ec;
    if (!exe.empty()) {
        const fs::path contents = fs::weakly_canonical(exe.parent_path().parent_path(), ec);
        if (!ec && !contents.empty()) {
            const fs::path bundled = contents / "Resources" / "branding" / std::string(fileName);
            if (fs::exists(bundled)) {
                return bundled;
            }
        }
    }

    const fs::path cwdRelative = fs::current_path(ec) / "assets" / "branding" / std::string(fileName);
    if (!ec && fs::exists(cwdRelative)) {
        return cwdRelative;
    }

    return {};
}

