void applyHdrspaceDockIconIfAvailable() {
#if defined(__APPLE__)
    const fs::path iconPath = hdrspaceBrandingResourcePath(kHdrspaceAppIconAsset);
    if (!fs::exists(iconPath)) {
        return;
    }

    const auto pathUtf8 = iconPath.string();
    auto* nsApplicationClass = reinterpret_cast<Class>(objc_getClass("NSApplication"));
    auto* nsImageClass = reinterpret_cast<Class>(objc_getClass("NSImage"));
    auto* nsStringClass = reinterpret_cast<Class>(objc_getClass("NSString"));
    if (!nsApplicationClass || !nsImageClass || !nsStringClass) {
        return;
    }

    auto* sharedApplication = reinterpret_cast<id (*)(Class, SEL)>(objc_msgSend)(
        nsApplicationClass,
        sel_registerName("sharedApplication")
    );
    auto* pathString = reinterpret_cast<id (*)(Class, SEL, const char*)>(objc_msgSend)(
        nsStringClass,
        sel_registerName("stringWithUTF8String:"),
        pathUtf8.c_str()
    );
    auto* imageAlloc = reinterpret_cast<id (*)(Class, SEL)>(objc_msgSend)(
        nsImageClass,
        sel_registerName("alloc")
    );
    auto* iconImage = reinterpret_cast<id (*)(id, SEL, id)>(objc_msgSend)(
        imageAlloc,
        sel_registerName("initWithContentsOfFile:"),
        pathString
    );
    if (sharedApplication && iconImage) {
        reinterpret_cast<void (*)(id, SEL, id)>(objc_msgSend)(
            sharedApplication,
            sel_registerName("setApplicationIconImage:"),
            iconImage
        );
    }
#endif
}

fs::path safeCurrentPath() {
    std::error_code ec;
    fs::path cwd = fs::current_path(ec);
    if (!ec && !cwd.empty()) {
        return cwd;
    }
    if (const char* home = std::getenv("HOME")) {
        fs::path homePath{home};
        if (!homePath.empty()) {
            return homePath;
        }
    }
    fs::path tempDir = fs::temp_directory_path(ec);
    if (!ec && !tempDir.empty()) {
        return tempDir;
    }
    return "/";
}

fs::path userLibrarySubdir(const fs::path& relativePath) {
    if (const char* home = std::getenv("HOME")) {
        fs::path homePath{home};
        if (!homePath.empty()) {
            return homePath / "Library" / relativePath;
        }
    }

    std::error_code ec;
    fs::path tempDir = fs::temp_directory_path(ec);
    if (!ec && !tempDir.empty()) {
        return tempDir / relativePath.filename();
    }

    return safeCurrentPath() / relativePath.filename();
}

std::string utf8FromCodepoint(int codepoint) {
    std::string out;
    if (codepoint <= 0x7F) {
        out.push_back(static_cast<char>(codepoint));
    } else if (codepoint <= 0x7FF) {
        out.push_back(static_cast<char>(0xC0 | ((codepoint >> 6) & 0x1F)));
        out.push_back(static_cast<char>(0x80 | (codepoint & 0x3F)));
    } else if (codepoint <= 0xFFFF) {
        out.push_back(static_cast<char>(0xE0 | ((codepoint >> 12) & 0x0F)));
        out.push_back(static_cast<char>(0x80 | ((codepoint >> 6) & 0x3F)));
        out.push_back(static_cast<char>(0x80 | (codepoint & 0x3F)));
    } else {
        out.push_back(static_cast<char>(0xF0 | ((codepoint >> 18) & 0x07)));
        out.push_back(static_cast<char>(0x80 | ((codepoint >> 12) & 0x3F)));
        out.push_back(static_cast<char>(0x80 | ((codepoint >> 6) & 0x3F)));
        out.push_back(static_cast<char>(0x80 | (codepoint & 0x3F)));
    }
    return out;
}

