// Small × close button: icon only, background on hover.
class CardCloseButton final : public nanogui::Button {
public:
    explicit CardCloseButton(Widget* parent) : Button(parent, "") {
        set_fixed_size({28, 28});
        set_tooltip("Close");
    }
    void draw(NVGcontext* ctx) override {
        const float x = m_pos.x(), y = m_pos.y(), w = m_size.x(), h = m_size.y();
        nvgSave(ctx);
        if (m_mouse_focus || m_pushed) {
            nvgBeginPath(ctx);
            nvgRoundedRect(ctx, x, y, w, h, 4.0f);
            nvgFillColor(ctx, Color(255, 255, 255, m_pushed ? 26 : 16));
            nvgFill(ctx);
        }
        const auto glyph = nanogui::utf8(FA_TIMES);
        nvgFontFace(ctx, "icons");
        nvgFontSize(ctx, 14.0f);
        nvgTextAlign(ctx, NVG_ALIGN_CENTER | NVG_ALIGN_MIDDLE);
        nvgFillColor(ctx, m_mouse_focus ? hdrspaceInk(240) : hdrspaceMutedInk(200));
        nvgText(ctx, x + w * 0.5f, y + h * 0.5f + 1.0f, glyph.data(), nullptr);
        nvgRestore(ctx);
    }
};

