private:
    static constexpr int kGlareBandSelection = -2;
    static constexpr int kGlareZone1Selection = -3;
    static constexpr int kGlareZone2Selection = -4;
    static constexpr int kInspectorContentWidth = 280;
    static constexpr int kInspectorFieldGap = 8;
    static constexpr int kInspectorHalfWidth = (kInspectorContentWidth - kInspectorFieldGap) / 2;
    static constexpr int kInspectorFieldWidth = kInspectorHalfWidth - 4;

    struct GlareSelectionMaskState {
        std::vector<uint8_t> mask;
        std::optional<tev::Box2i> bounds;
        std::string label;
    };

    struct RecentHdrEntry {
        fs::path path;
        std::vector<uint8_t> thumbnailRgba;
        Vector2i thumbnailSize{52, 34};
        bool loading = false;
    };

    static fs::path executablePath() {
        std::vector<char> buffer(4096, '\0');
        uint32_t size = static_cast<uint32_t>(buffer.size());
        if (_NSGetExecutablePath(buffer.data(), &size) != 0) {
            buffer.resize(size + 1, '\0');
            if (_NSGetExecutablePath(buffer.data(), &size) != 0) {
                throw std::runtime_error("Could not resolve executable path.");
            }
        }

        return fs::weakly_canonical(fs::path(buffer.data()));
    }

    static fs::path findOnPath(const std::string& name) {
        const char* pathEnv = std::getenv("PATH");
        if (!pathEnv) {
            return {};
        }

        std::stringstream ss{pathEnv};
        std::string entry;
        while (std::getline(ss, entry, ':')) {
            if (entry.empty()) {
                continue;
            }

            fs::path candidate = fs::path(entry) / name;
            if (fs::exists(candidate)) {
                return fs::weakly_canonical(candidate);
            }
        }

        return {};
    }

    static AppPaths resolvePaths() {
        AppPaths out;
        fs::path exe = executablePath();
        out.appRoot = fs::weakly_canonical(exe.parent_path().parent_path());
        const fs::path legacyCacheDir = out.appRoot / "build" / "cache";
        const fs::path legacySettingsFile = legacyCacheDir / "settings.conf";
        out.cacheDir = userLibrarySubdir("Caches/hdrspace");
        out.settingsFile = userLibrarySubdir("Application Support/hdrspace/settings.conf");
        out.aiRuntimeRoot = userLibrarySubdir("Application Support/hdrspace/mlx-sam3-runtime");
        out.aiHfHomeDir = userLibrarySubdir("Application Support/hdrspace/mlx-sam3-hf-home");
        out.da3RuntimeRoot = userLibrarySubdir("Application Support/hdrspace/da3-runtime");
        out.da3HfHomeDir = userLibrarySubdir("Application Support/hdrspace/da3-hf-home");
        const fs::path bundledProfilesDir = out.appRoot / "profiles";
        if (fs::exists(bundledProfilesDir)) {
            out.profilesDir = bundledProfilesDir;
        } else {
            out.profilesDir = out.appRoot.parent_path() / "mergehdr" / "profiles";
        }

        const fs::path bundledMergehdr = out.appRoot / "MacOS" / "mergehdr";
        if (fs::exists(bundledMergehdr)) {
            out.mergehdr = fs::weakly_canonical(bundledMergehdr);
        } else {
            out.mergehdr = out.appRoot.parent_path() / "mergehdr" / "bin" / "mergehdr";
            if (!fs::exists(out.mergehdr)) {
                out.mergehdr = findOnPath("mergehdr");
            }
        }

        const fs::path bundledOiiotool = out.appRoot / "MacOS" / "oiiotool";
        if (fs::exists(bundledOiiotool)) {
            out.oiiotool = fs::weakly_canonical(bundledOiiotool);
        } else {
            out.oiiotool = findOnPath("oiiotool");
            if (out.oiiotool.empty()) {
                fs::path brew{"/opt/homebrew/bin/oiiotool"};
                if (fs::exists(brew)) {
                    out.oiiotool = brew;
                }
            }
        }

        const fs::path bundledHdrvdp3DataDir = out.appRoot / "Resources" / "hdrvdp3" / "data";
        if (fs::exists(bundledHdrvdp3DataDir) && fs::is_directory(bundledHdrvdp3DataDir)) {
            out.hdrvdpDataDir = bundledHdrvdp3DataDir;
        }

        fs::create_directories(out.cacheDir);
        fs::create_directories(out.settingsFile.parent_path());

        if (!fs::exists(out.settingsFile) && fs::exists(legacySettingsFile)) {
            std::error_code copyError;
            fs::copy_file(legacySettingsFile, out.settingsFile, fs::copy_options::overwrite_existing, copyError);
        }

        auto settings = readKeyValueFile(out.settingsFile);
        if (!settings["mergehdrPath"].empty()) {
            fs::path configured = settings["mergehdrPath"];
            if (fs::exists(configured)) {
                out.mergehdr = fs::weakly_canonical(configured);
            }
        }
        if (!settings["oiiotoolPath"].empty()) {
            fs::path configured = settings["oiiotoolPath"];
            if (fs::exists(configured)) {
                out.oiiotool = fs::weakly_canonical(configured);
            }
        }

        const fs::path bundledRadianceRoot = out.appRoot / "Resources" / "radiance";
        const fs::path systemRadianceRoot = "/usr/local/radiance";
        if (fs::exists(bundledRadianceRoot / "bin") && fs::exists(bundledRadianceRoot / "lib")) {
            out.radianceRoot = bundledRadianceRoot;
            out.radianceBinDir = bundledRadianceRoot / "bin";
            out.radianceLibDir = bundledRadianceRoot / "lib";
        } else if (fs::exists(systemRadianceRoot / "bin") && fs::exists(systemRadianceRoot / "lib")) {
            out.radianceRoot = systemRadianceRoot;
            out.radianceBinDir = systemRadianceRoot / "bin";
            out.radianceLibDir = systemRadianceRoot / "lib";
        } else {
            const fs::path rxpiecePath = findOnPath("rxpiece");
            if (!rxpiecePath.empty()) {
                out.radianceBinDir = rxpiecePath.parent_path();
                const fs::path guessedRoot = out.radianceBinDir.parent_path();
                if (fs::exists(guessedRoot / "lib")) {
                    out.radianceRoot = guessedRoot;
                    out.radianceLibDir = guessedRoot / "lib";
                }
            }
        }
        return out;
    }

    fs::path radianceExecutablePath(const std::string& name) const {
        if (!paths_.radianceBinDir.empty()) {
            const fs::path bundled = paths_.radianceBinDir / name;
            if (fs::exists(bundled)) {
                return bundled;
            }
        }
        return findOnPath(name);
    }

    fs::path radianceLibraryPath(const std::string& name) const {
        if (!paths_.radianceLibDir.empty()) {
            const fs::path bundled = paths_.radianceLibDir / name;
            if (fs::exists(bundled)) {
                return bundled;
            }
        }
        const fs::path fallback = fs::path("/usr/local/radiance/lib") / name;
        if (fs::exists(fallback)) {
            return fallback;
        }
        return {};
    }

    std::string createViewShellEnvironmentPrefix() const {
        std::ostringstream env;
        if (!paths_.radianceBinDir.empty()) {
            env << "export PATH=" << shellQuote(paths_.radianceBinDir.string()) << ":\"$PATH\" && ";
        }
        if (!paths_.radianceLibDir.empty()) {
            env << "export RAYPATH=" << shellQuote(paths_.radianceLibDir.string()) << ":\"${RAYPATH:-}\" && ";
        }
        return env.str();
    }

    void runOnUiThreadSync(const std::function<void()>& fn) {
        if (!viewer_) {
            throw std::runtime_error("Demo mode requires an active viewer.");
        }
        auto promise = std::make_shared<std::promise<void>>();
        auto future = promise->get_future();
        viewer_->scheduleToUiThread([fn, promise]() mutable {
            try {
                fn();
                promise->set_value();
            } catch (...) {
                try {
                    promise->set_exception(std::current_exception());
                } catch (...) {
                }
            }
        });
        future.get();
    }

    template <typename Fn>
    auto callOnUiThreadSync(Fn&& fn) -> decltype(fn()) {
        using Result = decltype(fn());
        if (!viewer_) {
            throw std::runtime_error("Demo mode requires an active viewer.");
        }
        auto promise = std::make_shared<std::promise<Result>>();
        auto future = promise->get_future();
        viewer_->scheduleToUiThread([fn = std::forward<Fn>(fn), promise]() mutable {
            try {
                promise->set_value(fn());
            } catch (...) {
                try {
                    promise->set_exception(std::current_exception());
                } catch (...) {
                }
            }
        });
        return future.get();
    }

    bool waitForUiCondition(const std::function<bool()>& predicate,
                            std::chrono::milliseconds timeout,
                            std::chrono::milliseconds poll = 120ms) {
        const auto start = std::chrono::steady_clock::now();
        while (!tev::shuttingDown()) {
            if (callOnUiThreadSync([&]() { return predicate(); })) {
                return true;
            }
            if (std::chrono::steady_clock::now() - start >= timeout) {
                return false;
            }
            std::this_thread::sleep_for(poll);
        }
        return false;
    }

    static bool samePathForDemo(const fs::path& a, const fs::path& b) {
        if (a.empty() || b.empty()) {
            return false;
        }
        std::error_code aEc;
        std::error_code bEc;
        const fs::path ca = fs::weakly_canonical(a, aEc);
        const fs::path cb = fs::weakly_canonical(b, bEc);
        if (!aEc && !bEc) {
            return ca == cb;
        }
        return a.lexically_normal() == b.lexically_normal();
    }

    static std::vector<fs::path> collectDemoRawFiles(const fs::path& dir) {
        std::vector<fs::path> out;
        if (!fs::exists(dir) || !fs::is_directory(dir)) {
            return out;
        }
        for (const auto& entry : fs::directory_iterator(dir)) {
            if (!entry.is_regular_file()) {
                continue;
            }
            const std::string ext = tev::toLower(entry.path().extension().string());
            if (ext == ".cr3") {
                out.push_back(entry.path());
            }
        }
        std::sort(out.begin(), out.end());
        return out;
    }

    void finishHiddenFukuokaDemo(const HiddenFukuokaDemoOptions& options, const std::optional<std::string>& error = std::nullopt) {
        viewer_->scheduleToUiThread([this, options, error]() {
            if (error.has_value()) {
                std::cerr << "[demo] Failed: " << *error << std::endl;
                showMessage("Fukuoka demo failed:\n" + *error);
            } else {
                std::cout << "[demo] Finished successfully." << std::endl;
            }
            if (options.quitOnFinish && viewer_ && viewer_->glfw_window()) {
                glfwSetWindowShouldClose(viewer_->glfw_window(), GLFW_TRUE);
            }
        });
    }

    void runHiddenFukuokaDemoWorker(HiddenFukuokaDemoOptions options) {
        try {
            if (options.assetsDir.empty()) {
                options.assetsDir = paths_.cacheDir / "fukuoka_demo_assets";
            }
            options.assetsDir = fs::absolute(options.assetsDir);

            const auto rawFiles = collectDemoRawFiles(options.assetsDir);
            if (rawFiles.empty()) {
                throw std::runtime_error("No CR3 files were found in " + options.assetsDir.string());
            }

            const fs::path roomPath = options.assetsDir / "solskin_room_double_glazing.rad";
            const fs::path viewPath = options.assetsDir / "15m_updated.vf";
            const fs::path envPath = options.assetsDir / "00157_01.hdr";
            const fs::path mergeOutputPath = options.assetsDir / "fukuoka_demo_merge.hdr";
            const fs::path visibilityReferencePath = options.assetsDir / "157_clear_view_render.hdr";
            const fs::path visibilityTestPath =
                fs::exists(options.assetsDir / "157_blind_view_renderer.hdr")
                    ? options.assetsDir / "157_blind_view_renderer.hdr"
                    : (fs::exists(options.assetsDir / "157_1_blind_sm.hdr")
                        ? options.assetsDir / "157_1_blind_sm.hdr"
                        : options.assetsDir / "157_1_blind.hdr");
            const fs::path visibilityMaskPath = options.assetsDir / "white_ref.hdr";

            if (!fs::exists(roomPath) || !fs::exists(viewPath) || !fs::exists(envPath)) {
                throw std::runtime_error("The demo asset folder is missing one of: solskin_room_double_glazing.rad, 15m_updated.vf, 00157_01.hdr");
            }
            if (!fs::exists(visibilityReferencePath) || !fs::exists(visibilityTestPath) || !fs::exists(visibilityMaskPath)) {
                throw std::runtime_error(
                    "The demo asset folder is missing one of: 157_clear_view_render.hdr, 157_blind_view_renderer.hdr (or 157_1_blind_sm.hdr / 157_1_blind.hdr), white_ref.hdr"
                );
            }

            std::cout << "[demo] Starting hidden Fukuoka demo using assets in " << options.assetsDir << std::endl;

            runOnUiThreadSync([this, &options]() {
                if (options.maximizeWindow && viewer_ && viewer_->glfw_window()) {
                    glfwRestoreWindow(viewer_->glfw_window());
                    glfwMaximizeWindow(viewer_->glfw_window());
                }
                viewer_->set_visible(true);
                viewer_->focusWindow();
                viewer_->setUiVisible(true);
                viewer_->perform_layout(viewer_->nvg_context());
                viewer_->redraw();
            });
            std::this_thread::sleep_for(1200ms);

            std::cout << "[demo] Preparing merge inputs..." << std::endl;
            runOnUiThreadSync([this, &rawFiles, &mergeOutputPath]() {
                setActiveRightPlane(RightPlane::MergeHdr);
                inputFiles_.clear();
                inputFiles_.reserve(rawFiles.size());
                for (const auto& rawFile : rawFiles) {
                    inputFiles_.push_back(rawFile.string());
                }
                workingDir_ = rawFiles.front().parent_path();
                outputFolderBox_->set_value(mergeOutputPath.parent_path().string());
                outputNameBox_->set_value(mergeOutputPath.filename().string());
                outputFormatCombo_->set_selected_index(0);
                if (inputSummaryLabel_) {
                    inputSummaryLabel_->set_caption(summarizeSelectedFiles(inputFiles_));
                }

                const auto it = std::find(profileNames_.begin(), profileNames_.end(), "R5m2");
                if (it == profileNames_.end()) {
                    throw std::runtime_error("The R5m2 profile was not found.");
                }
                const int profileIndex = static_cast<int>(std::distance(profileNames_.begin(), it)) + 1;
                profileCombo_->set_selected_index(profileIndex);
                applyProfileFromSelection(profileIndex);
                viewer_->redraw();
            });
            std::this_thread::sleep_for(1500ms);
            std::this_thread::sleep_for(1800ms);

            std::cout << "[demo] Running merge..." << std::endl;
            runOnUiThreadSync([this]() {
                startMerge();
                viewer_->redraw();
            });

            if (!waitForUiCondition([this, &mergeOutputPath]() {
                    const bool inactive = !mergeJob_.active;
                    if (!inactive || !viewer_ || !viewer_->currentImage()) {
                        return false;
                    }
                    return samePathForDemo(viewer_->currentImage()->path(), mergeOutputPath);
                }, 10min)) {
                throw std::runtime_error("Timed out while waiting for the merge result to load.");
            }
            std::this_thread::sleep_for(1600ms);

            std::cout << "[demo] Switching to luminance view..." << std::endl;
            runOnUiThreadSync([this]() {
                setActiveRightPlane(RightPlane::ImageViewer);
                viewer_->setInspectionPresetIndex(5);
                viewer_->setAutoFitToScreen(true);
                viewer_->focusWindow();
                viewer_->redraw();
            });
            std::this_thread::sleep_for(1400ms);

            std::cout << "[demo] Normalizing exposure..." << std::endl;
            runOnUiThreadSync([this]() {
                viewer_->normalizeExposureAndOffset();
                viewer_->redraw();
            });
            std::this_thread::sleep_for(1600ms);

            std::cout << "[demo] Running image statistics..." << std::endl;
            runOnUiThreadSync([this]() {
                setActiveRightPlane(RightPlane::ImageStatistics);
                runImageStatistics();
                viewer_->redraw();
            });
            if (!waitForUiCondition([this]() { return imageStatsResult_.has_value() && imageStatsResult_->ok; }, 2min)) {
                throw std::runtime_error("Timed out while waiting for image statistics.");
            }
            std::this_thread::sleep_for(1800ms);

            std::cout << "[demo] Running glare analysis..." << std::endl;
            runOnUiThreadSync([this]() {
                setActiveRightPlane(RightPlane::EvaluateGlare);
                glareThresholdBox_->set_value("5000");
                viewer_->redraw();
            });
            std::this_thread::sleep_for(1200ms);
            runOnUiThreadSync([this]() {
                startGlareEvaluation();
                viewer_->redraw();
            });
            if (!waitForUiCondition([this]() {
                    std::lock_guard<std::mutex> lock{glareTask_.mutex};
                    return !glareTask_.active && glareResult_.has_value();
                }, 3min)) {
                throw std::runtime_error("Timed out while waiting for glare analysis.");
            }
            std::this_thread::sleep_for(2200ms);

            std::cout << "[demo] Clearing canvas and switching to Create..." << std::endl;
            runOnUiThreadSync([this]() {
                setActiveRightPlane(RightPlane::ImageViewer);
                viewer_->clearAnalysisOverlay();
                viewer_->removeAllImages();
                glareUiImageKey_ = nullptr;
                clearGlareSelectionProfileResult();
                refreshGlareUi();
                viewer_->redraw();
            });
            std::this_thread::sleep_for(1200ms);

            runOnUiThreadSync([this, &roomPath, &viewPath, &envPath]() {
                setActiveRightPlane(RightPlane::CreateView);
                createViewRoomBox_->set_value(roomPath.string());
                createViewViewBox_->set_value(viewPath.string());
                createViewEnvironmentBox_->set_value(envPath.string());
                refreshCreateViewAnalysis();
                viewer_->redraw();
            });
            std::this_thread::sleep_for(2200ms);

            std::cout << "[demo] Zooming out the Create View 3D canvas..." << std::endl;
            runOnUiThreadSync([this]() {
                if (createViewCanvasPreview_) {
                    createViewCanvasPreview_->setProgrammaticView(0.10f);
                }
                if (createViewPreviewWidget_) {
                    createViewPreviewWidget_->setProgrammaticView(0.10f);
                }
                viewer_->redraw();
            });
            std::this_thread::sleep_for(2200ms);

            std::cout << "[demo] Running Create View preview..." << std::endl;
            runOnUiThreadSync([this]() {
                startCreateViewQuickPreview();
                viewer_->redraw();
            });
            if (!waitForUiCondition([this]() {
                    std::lock_guard<std::mutex> lock{createViewQuickPreviewState_.mutex};
                    return !createViewQuickPreviewState_.active &&
                        createViewCanvasRenderPreview_ &&
                        createViewCanvasRenderPreview_->hasPreviewImage();
                }, 3min)) {
                throw std::runtime_error("Timed out while waiting for the Create View preview.");
            }
            std::this_thread::sleep_for(3200ms);

            std::cout << "[demo] Loading visibility compare pair..." << std::endl;
            runOnUiThreadSync([this, &visibilityReferencePath, &visibilityTestPath, &visibilityMaskPath]() {
                setActiveRightPlane(RightPlane::ViewVisibility);
                viewVisibilityReferenceBox_->set_value(visibilityReferencePath.string());
                viewVisibilityTestBox_->set_value(visibilityTestPath.string());
                viewVisibilityMaskBox_->set_value(visibilityMaskPath.string());
                resetViewVisibilityResult();
                loadViewVisibilityPairIntoCanvas();
                viewer_->redraw();
            });
            if (!waitForUiCondition([this, &visibilityReferencePath, &visibilityTestPath]() {
                    if (!viewer_ || pendingViewVisibilityPair_.has_value()) {
                        return false;
                    }
                    if (!viewer_->currentImage() || !viewer_->currentReference()) {
                        return false;
                    }
                    return samePathForDemo(viewer_->currentImage()->path(), visibilityTestPath) &&
                           samePathForDemo(viewer_->currentReference()->path(), visibilityReferencePath);
                }, 2min)) {
                throw std::runtime_error("Timed out while loading the view visibility image pair.");
            }
            std::this_thread::sleep_for(2200ms);

            std::cout << "[demo] Computing visibility..." << std::endl;
            runOnUiThreadSync([this]() {
                computeViewVisibilitySummary();
                viewer_->redraw();
            });
            if (!waitForUiCondition([this]() { return viewVisibilityResult_.has_value(); }, 2min)) {
                throw std::runtime_error("Timed out while waiting for view visibility computation.");
            }
            std::this_thread::sleep_for(3200ms);

            finishHiddenFukuokaDemo(options);
        } catch (const std::exception& e) {
            finishHiddenFukuokaDemo(options, e.what());
        }
    }

