    void buildUi() {
        controlsWindow_ = new DesktopPanelWindow(viewer_, "Merge HDR");
        controlsWindow_->set_position({14, 14});
        controlsWindow_->set_fixed_size({272, 900});
        controlsWindow_->set_size({272, 900});
        controlsWindow_->setMovable(false);
        controlsWindow_->set_layout(new BoxLayout{Orientation::Vertical, Alignment::Fill, 4, 0});
        controlsWindow_->setBeforeDraw([this] { applyControlsPlacement(); });
        auto* toolbar = new Widget(controlsWindow_);
        toolbar->set_layout(new GridLayout{Orientation::Horizontal, 1, Alignment::Fill, 6, 0});
        createPanelHeader(toolbar, "Merge HDR");

        controlsScroll_ = new DesktopScrollPanel(controlsWindow_);
        controlsScroll_->set_fixed_size({256, 850});
        controlsScroll_->set_size({256, 850});
        auto* content = new Widget(controlsScroll_);
        content->set_layout(new BoxLayout{Orientation::Vertical, Alignment::Fill, 0, 5});

        auto* sectionRowTop = new Widget(content);
        sectionRowTop->set_layout(new GridLayout{Orientation::Horizontal, 3, Alignment::Fill, 5, 2});
        auto* sectionRowBottom = new Widget(content);
        sectionRowBottom->set_layout(new GridLayout{Orientation::Horizontal, 2, Alignment::Fill, 5, 2});

        auto makeSectionButton = [&](Widget* row, const std::string& caption, LeftSection section) {
            auto* button = new Button(row, caption);
            button->set_flags(Button::ToggleButton);
            styleSectionButton(button, leftSectionIcon(section));
            button->set_change_callback([this, section](bool pushed) {
                if (pushed) {
                    setActiveSection(section);
                }
            });
            leftSectionButtons_.emplace_back(section, button);
            return button;
        };

        makeSectionButton(sectionRowTop, "Merge", LeftSection::Merge);
        makeSectionButton(sectionRowTop, "Color", LeftSection::Color);
        makeSectionButton(sectionRowTop, "Shutter", LeftSection::Shutter);
        makeSectionButton(sectionRowBottom, "Aperture", LeftSection::Aperture);
        makeSectionButton(sectionRowBottom, "Settings", LeftSection::Settings);

        // Calibrate groups the three camera calibrations under one rail entry. This
        // segmented row switches between their existing pages; the pages are unchanged.
        calibrationTabsRow_ = new Widget(content);
        calibrationTabsRow_->set_layout(new GridLayout{Orientation::Horizontal, 3, Alignment::Fill, 0, 0});
        for (const LeftSection section : {LeftSection::Color, LeftSection::Shutter, LeftSection::Aperture}) {
            auto* tab = new HdrspaceTabButton(calibrationTabsRow_, mergeSectionLabel(section));
            tab->set_font_size(14);
            tab->set_fixed_size({kInspectorContentWidth / 3, 32});
            tab->set_tooltip(mergeSectionLabel(section) + " calibration");
            tab->set_change_callback([this, section](bool pushed) {
                if (pushed) {
                    setActiveSection(section);
                }
            });
            calibrationTabs_.emplace_back(section, tab);
        }
        calibrationTabsRow_->set_visible(false);

        leftPagesHost_ = new Widget(content);
        leftPagesHost_->set_layout(new BoxLayout{Orientation::Vertical, Alignment::Fill, 0, 0});

        auto* mergeTab = new Widget(leftPagesHost_);
        mergeTab->set_layout(new BoxLayout{Orientation::Vertical, Alignment::Fill, 0, 6});
        buildMergeTab(mergeTab);
        leftPages_.emplace_back(LeftSection::Merge, mergeTab);

        auto* colorTab = new Widget(leftPagesHost_);
        colorTab->set_layout(new BoxLayout{Orientation::Vertical, Alignment::Fill, 0, 6});
        buildColorTab(colorTab);
        leftPages_.emplace_back(LeftSection::Color, colorTab);

        auto* shutterTab = new Widget(leftPagesHost_);
        shutterTab->set_layout(new BoxLayout{Orientation::Vertical, Alignment::Fill, 0, 6});
        buildShutterTab(shutterTab);
        leftPages_.emplace_back(LeftSection::Shutter, shutterTab);

        auto* apertureTab = new Widget(leftPagesHost_);
        apertureTab->set_layout(new BoxLayout{Orientation::Vertical, Alignment::Fill, 0, 6});
        buildApertureTab(apertureTab);
        leftPages_.emplace_back(LeftSection::Aperture, apertureTab);

        auto* settingsTab = new Widget(leftPagesHost_);
        settingsTab->set_layout(new BoxLayout{Orientation::Vertical, Alignment::Fill, 0, 6});
        buildSettingsTab(settingsTab);
        leftPages_.emplace_back(LeftSection::Settings, settingsTab);

        sectionRowTop->set_visible(false);
        sectionRowBottom->set_visible(false);
        setActiveSection(LeftSection::Merge);

        applyControlsPlacement();
    }

    void setViewVisibilityStatusCaption(const std::string& message) {
        if (viewVisibilityStatusLabel_) {
            viewVisibilityStatusLabel_->set_caption(message);
        }
        updateContextStripUi();
    }

    tev::EMetric selectedViewVisibilityMetric() const {
        const int index = viewVisibilityMetricCombo_ ? viewVisibilityMetricCombo_->selected_index() : 1;
        switch (index) {
        case 0: return tev::EMetric::Error;
        case 1: return tev::EMetric::AbsoluteError;
        case 2: return tev::EMetric::SquaredError;
        case 3: return tev::EMetric::RelativeAbsoluteError;
        case 4: return tev::EMetric::RelativeSquaredError;
        default: return tev::EMetric::AbsoluteError;
        }
    }

    void tryActivatePendingViewVisibilityPair() {
        if (!pendingViewVisibilityPair_ || !viewer_ || activatingViewVisibilityPair_) {
            return;
        }
        activatingViewVisibilityPair_ = true;
        const auto activationGuard = tev::ScopeGuard{[this] { activatingViewVisibilityPair_ = false; }};

        const auto reference = viewer_->imageByPath(pendingViewVisibilityPair_->referencePath);
        const auto test = viewer_->imageByPath(pendingViewVisibilityPair_->testPath);
        if (!reference || !test) {
            return;
        }

        viewer_->clearAnalysisOverlay();
        viewer_->selectImage(test);
        viewer_->selectReference(reference);
        viewer_->setMetric(selectedViewVisibilityMetric());
        viewer_->setAutoFitToScreen(true);
        viewer_->focusWindow();

        setViewVisibilityStatusCaption(std::format(
            "Comparing {} against {} on the canvas.",
            test->shortName(),
            reference->shortName()
        ));

        pendingViewVisibilityPair_.reset();
        viewer_->redraw();
    }

    void loadViewVisibilityPairIntoCanvas(bool preserveResult = false) {
        if (!viewer_) {
            return;
        }

        const fs::path referencePath = normalizedTextBoxValue(viewVisibilityReferenceBox_ ? viewVisibilityReferenceBox_->value() : "");
        const fs::path testPath = normalizedTextBoxValue(viewVisibilityTestBox_ ? viewVisibilityTestBox_->value() : "");

        if (referencePath.empty() || testPath.empty()) {
            showMessage("Choose both reference and test HDR images first.");
            return;
        }
        if (!fs::exists(referencePath) || !fs::exists(testPath)) {
            showMessage("Reference or test image does not exist.");
            return;
        }
        if (fs::equivalent(referencePath, testPath)) {
            showMessage("Reference and test images must be different files.");
            return;
        }

        viewer_->setFilter("");
        viewer_->clearAnalysisOverlay();

        if (!viewer_->imageByPath(referencePath)) {
            imagesLoader_->enqueue(referencePath, "", false, nullptr);
        }
        if (!viewer_->imageByPath(testPath)) {
            imagesLoader_->enqueue(testPath, "", false, nullptr);
        }

        pendingViewVisibilityPair_ = PendingViewVisibilityPair{referencePath, testPath};
        if (!preserveResult) resetViewVisibilityResult();
        setViewVisibilityStatusCaption("Loading reference and test images...");
        tryActivatePendingViewVisibilityPair();
    }

    void previewViewVisibilityImage(const fs::path& path, std::string_view roleLabel, bool preserveResult = false) {
        if (!viewer_) {
            return;
        }

        pendingViewVisibilityPair_.reset();
        viewer_->selectReference(nullptr);
        viewer_->setMetric(selectedViewVisibilityMetric());
        if (!preserveResult) resetViewVisibilityResult();
        loadImageIntoViewer(path);
        setViewVisibilityStatusCaption(std::format("{} preview loaded on the canvas.", roleLabel));
    }

    void clearViewVisibilityCompare() {
        if (!viewer_) {
            return;
        }
        pendingViewVisibilityPair_.reset();
        viewer_->selectReference(nullptr);
        resetViewVisibilityResult();
        setViewVisibilityStatusCaption("Reference cleared. Canvas is showing a single image again.");
        viewer_->redraw();
    }

    std::shared_ptr<tev::Image> viewVisibilityImageForAnalysis(const fs::path& path) const {
        if (path.empty() || !fs::exists(path) || !imagesLoader_) {
            return nullptr;
        }

        if (viewer_) {
            if (auto existing = viewer_->imageByPath(path)) {
                return existing;
            }
        }

        auto loaded = tev::tryLoadImage(path, "", imagesLoader_->imageLoaderSettings(), imagesLoader_->groupChannels()).get();
        if (loaded.empty()) {
            return nullptr;
        }

        return loaded.front();
    }

    const tev::Channel* viewVisibilityRgbChannel(const tev::Image& image, std::string_view name) const {
        if (image.hasSourceChannels()) {
            if (const auto* source = image.sourceChannel(name)) {
                return source;
            }
        }
        return image.channel(name);
    }

    const tev::Channel* viewVisibilityMaskChannel(const tev::Image& image) const {
        if (image.hasSourceChannels() && !image.sourceChannels().empty()) {
            return &image.sourceChannels().front();
        }

        if (const auto* y = image.channel("Y")) {
            return y;
        }
        if (const auto* r = image.channel("R")) {
            return r;
        }
        if (!image.channelGroups().empty() && !image.channelGroups().front().channels.empty()) {
            return image.channel(image.channelGroups().front().channels.front());
        }
        return nullptr;
    }

    static std::string formatViewVisibilityScalar(double value, int decimals = 6) {
        if (!std::isfinite(value)) {
            return "--";
        }
        return std::format("{:.{}f}", value, decimals);
    }

    fs::path viewVisibilityTempResultPath() const {
        const fs::path referencePath = normalizedTextBoxValue(viewVisibilityReferenceBox_ ? viewVisibilityReferenceBox_->value() : "");
        const fs::path testPath = normalizedTextBoxValue(viewVisibilityTestBox_ ? viewVisibilityTestBox_->value() : "");
        const std::string modeSuffix =
            (viewVisibilityDetailCombo_ && viewVisibilityDetailCombo_->selected_index() == 1)
                ? "contrast_proxy"
                : "hdrvdp3";
        const std::string inputColorSuffix =
            viewVisibilityInputColorCombo_ && viewVisibilityInputColorCombo_->selected_index() == 2
                ? "xyz"
                : (viewVisibilityInputColorCombo_ && viewVisibilityInputColorCombo_->selected_index() == 1 ? "srgb" : "rad");
        const std::string stem = sanitizeStem(
            (referencePath.empty() ? std::string("reference") : referencePath.stem().string()) + "_" +
            (testPath.empty() ? std::string("test") : testPath.stem().string()) + "_" + modeSuffix + "_" + inputColorSuffix
        );
        return paths_.cacheDir / (stem + "_view_visibility_result.hdr");
    }

    void resetViewVisibilityResult() {
        viewVisibilityResult_.reset();
        setViewVisibilitySummaryCaption(
            "View size: --\n"
            "Reference baseline: --\n"
            "Visibility ratio: --\n"
            "Quality: --\n"
            "Input color: --"
        );
        updateContextStripUi();
        refreshHdrspaceNavigation();
    }

    std::string viewVisibilityViewSizeLabel() const {
        return viewVisibilityResult_
            ? std::format("{:L}", static_cast<long long>(std::llround(viewVisibilityResult_->viewSize)))
            : "--";
    }

    std::string viewVisibilityReferenceBaselineLabel() const {
        return viewVisibilityResult_
            ? formatViewVisibilityScalar(viewVisibilityResult_->referenceBaseline)
            : "--";
    }

    std::string viewVisibilityRatioLabel() const {
        return viewVisibilityResult_
            ? formatViewVisibilityScalar(viewVisibilityResult_->visibilityRatio)
            : "--";
    }

    std::string viewVisibilityQualityLabel() const {
        return viewVisibilityResult_
            ? formatViewVisibilityScalar(viewVisibilityResult_->qualityScore, 3)
            : "--";
    }

    std::string viewVisibilityDetailLabel() const {
        return viewVisibilityResult_
            ? viewVisibilityResult_->detailLabel
            : (viewVisibilityDetailCombo_ && viewVisibilityDetailCombo_->selected_index() == 1 ? "Contrast proxy" : "HDR-VDP3");
    }

    ViewVisibilitySummaryOptions::InputColor selectedViewVisibilityInputColor() const {
        const int index = viewVisibilityInputColorCombo_ ? viewVisibilityInputColorCombo_->selected_index() : 0;
        switch (index) {
            case 1: return ViewVisibilitySummaryOptions::InputColor::Srgb;
            case 2: return ViewVisibilitySummaryOptions::InputColor::Xyz;
            default: return ViewVisibilitySummaryOptions::InputColor::Rad;
        }
    }

    std::string viewVisibilityInputColorLabel() const {
        if (viewVisibilityResult_ && !viewVisibilityResult_->inputColor.empty()) {
            if (viewVisibilityResult_->inputColor == "xyz") return "XYZ";
            if (viewVisibilityResult_->inputColor == "srgb") return "sRGB";
            return "Radiance RGB";
        }
        switch (selectedViewVisibilityInputColor()) {
            case ViewVisibilitySummaryOptions::InputColor::Srgb: return "sRGB";
            case ViewVisibilitySummaryOptions::InputColor::Xyz: return "XYZ";
            case ViewVisibilitySummaryOptions::InputColor::Rad:
            default: return "Radiance RGB";
        }
    }

    tev::EChannelMask selectedViewVisibilityChannelMask() const {
        const int index = viewVisibilityResultMapCombo_ ? viewVisibilityResultMapCombo_->selected_index() : 1;
        switch (index) {
            case 1: return tev::EChannelMask::Green;
            case 2: return tev::EChannelMask::Red;
            case 3: return tev::EChannelMask::Blue;
            default: return tev::EChannelMask::Red | tev::EChannelMask::Green | tev::EChannelMask::Blue;
        }
    }

    void applyViewVisibilityResultDisplay(bool updateStatus = true) {
        if (!viewer_ || !viewVisibilityResult_ || viewVisibilityResult_->resultPath.empty() || !fs::exists(viewVisibilityResult_->resultPath)) {
            return;
        }

        const bool alreadyShowingResult =
            viewer_->currentImage() &&
            !viewer_->currentImage()->path().empty() &&
            fs::equivalent(viewer_->currentImage()->path(), viewVisibilityResult_->resultPath);

        pendingViewVisibilityPair_.reset();
        viewer_->selectReference(nullptr);
        if (!alreadyShowingResult) {
            loadImageIntoViewer(viewVisibilityResult_->resultPath);
        }
        viewer_->setInspectionPresetIndex(0);
        viewer_->setMetric(selectedViewVisibilityMetric());
        viewer_->selectGroup("RGB");
        if (auto* canvas = viewer_->imageCanvas()) {
            canvas->setChannelMask(selectedViewVisibilityChannelMask());
        }
        if (updateStatus) {
            setViewVisibilityStatusCaption("View visibility result loaded on the canvas.");
        }
        viewer_->redraw();
        updateContextStripUi();
        hdrspaceVisibilityPreview_ = 4;
        refreshHdrspaceNavigation();
    }

    void previewViewVisibilityResult() {
        if (!viewVisibilityResult_ || viewVisibilityResult_->resultPath.empty() || !fs::exists(viewVisibilityResult_->resultPath)) {
            showMessage("Compute visibility first.");
            return;
        }
        applyViewVisibilityResultDisplay();
    }

    void saveViewVisibilityResult() {
        if (!viewVisibilityResult_ || viewVisibilityResult_->resultPath.empty() || !fs::exists(viewVisibilityResult_->resultPath)) {
            showMessage("Compute visibility first.");
            return;
        }

        const auto paths = file_dialog(
            viewer_,
            FileDialogType::Save,
            {
                {"hdr", "HDR image"},
            },
            viewVisibilityResult_->resultPath.filename().string()
        );
        if (paths.empty()) {
            return;
        }
        fs::path outputPath = paths.front();
        outputPath.replace_extension(".hdr");

        try {
            fs::copy_file(viewVisibilityResult_->resultPath, outputPath, fs::copy_options::overwrite_existing);
            showMessage("View visibility HDR saved:\n" + outputPath.string());
        } catch (const std::exception& e) {
            showMessage(std::string("Failed to save view visibility HDR: ") + e.what());
        }
    }

    void exportViewVisibilityStepMaps() {
        const fs::path referencePath = normalizedTextBoxValue(viewVisibilityReferenceBox_ ? viewVisibilityReferenceBox_->value() : "");
        const fs::path testPath = normalizedTextBoxValue(viewVisibilityTestBox_ ? viewVisibilityTestBox_->value() : "");
        const fs::path maskPath = normalizedTextBoxValue(viewVisibilityMaskBox_ ? viewVisibilityMaskBox_->value() : "");
        const std::string ppdText = normalizedTextBoxValue(viewVisibilityPpdBox_ ? viewVisibilityPpdBox_->value() : "");
        const std::string sensitivityText = normalizedTextBoxValue(viewVisibilitySensitivityBox_ ? viewVisibilitySensitivityBox_->value() : "");
        const std::string spectralText = normalizedTextBoxValue(viewVisibilitySpectralBox_ ? viewVisibilitySpectralBox_->value() : "");

        if (referencePath.empty() || testPath.empty()) {
            showMessage("Choose both reference and test HDR images first.");
            return;
        }
        if (maskPath.empty()) {
            showMessage("Choose a white mask HDR first.");
            return;
        }
        if (viewVisibilityDetailCombo_ && viewVisibilityDetailCombo_->selected_index() == 1) {
            showMessage("Step map export is available for HDR-VDP3 detail mode.");
            return;
        }

        const auto folders = file_dialog(
            viewer_,
            FileDialogType::PickFolder,
            {},
            paths_.cacheDir.string()
        );
        if (folders.empty()) {
            return;
        }

        try {
            ViewVisibilitySummaryOptions opts;
            opts.referencePath = referencePath.string();
            opts.testPath = testPath.string();
            opts.maskPath = maskPath.string();
            opts.pixelsPerDegree = ppdText.empty() ? 30.0 : std::stod(ppdText);
            opts.sensitivityCorrection = sensitivityText.empty() ? -1.0 : std::stod(sensitivityText);
            const fs::path spectralPath = resolveViewVisibilitySpectralPath(spectralText);
            if (!spectralPath.empty()) {
                opts.spectralEmissionPath = spectralPath.string();
            }
            opts.detailMode = ViewVisibilitySummaryOptions::DetailMode::HdrvdpSubset;
            opts.inputColor = selectedViewVisibilityInputColor();

            const fs::path outputDir = fs::path(folders.front()) /
                (sanitizeStem(referencePath) + "_" + sanitizeStem(testPath) + "_view_visibility_steps");
            setViewVisibilityStatusCaption("Exporting native visibility step maps...");
            writeViewVisibilityDebugDump(opts, outputDir.string());
            setViewVisibilityStatusCaption("Native visibility step maps exported.");
            showMessage("View visibility step maps saved:\n" + outputDir.string());
        } catch (const std::exception& e) {
            setViewVisibilityStatusCaption("Step map export failed.");
            showMessage(std::string("Failed to export view visibility step maps: ") + e.what());
        }
    }

    void setViewVisibilitySummaryCaption(const std::string& message) {
        if (viewVisibilitySummaryLabel_) {
            viewVisibilitySummaryLabel_->set_caption(message);
        }
    }

    fs::path resolveViewVisibilitySpectralPath(const std::string& text) const {
        const fs::path spectralPath = normalizedTextBoxValue(text);
        if (spectralPath.empty()) {
            return {};
        }
        if (spectralPath.is_absolute()) {
            return spectralPath;
        }
        if (!paths_.hdrvdpDataDir.empty()) {
            const fs::path directMatch = paths_.hdrvdpDataDir / spectralPath;
            if (fs::exists(directMatch)) {
                return directMatch;
            }
            const fs::path inDataRoot = paths_.hdrvdpDataDir / "data" / spectralPath;
            if (fs::exists(inDataRoot)) {
                return inDataRoot;
            }
        }
        return spectralPath;
    }

    fs::path defaultViewVisibilitySpectralPath() const {
        if (!paths_.hdrvdpDataDir.empty()) {
            const fs::path oled = paths_.hdrvdpDataDir / "emission_spectra_oled.csv";
            if (fs::exists(oled)) {
                return oled;
            }
        }
        return "data/emission_spectra_oled.csv";
    }

    void computeViewVisibilitySummary() {
        const fs::path referencePath = normalizedTextBoxValue(viewVisibilityReferenceBox_ ? viewVisibilityReferenceBox_->value() : "");
        const fs::path testPath = normalizedTextBoxValue(viewVisibilityTestBox_ ? viewVisibilityTestBox_->value() : "");
        const fs::path maskPath = normalizedTextBoxValue(viewVisibilityMaskBox_ ? viewVisibilityMaskBox_->value() : "");
        const std::string ppdText = normalizedTextBoxValue(viewVisibilityPpdBox_ ? viewVisibilityPpdBox_->value() : "");
        const std::string sensitivityText = normalizedTextBoxValue(viewVisibilitySensitivityBox_ ? viewVisibilitySensitivityBox_->value() : "");
        const std::string spectralText = normalizedTextBoxValue(viewVisibilitySpectralBox_ ? viewVisibilitySpectralBox_->value() : "");

        if (referencePath.empty() || testPath.empty()) {
            showMessage("Choose both reference and test HDR images first.");
            return;
        }
        if (maskPath.empty()) {
            showMessage("Choose a white mask HDR first.");
            return;
        }

        try {
            ViewVisibilitySummaryOptions opts;
            opts.referencePath = referencePath.string();
            opts.testPath = testPath.string();
            opts.maskPath = maskPath.string();
            opts.pixelsPerDegree = ppdText.empty() ? 30.0 : std::stod(ppdText);
            opts.sensitivityCorrection = sensitivityText.empty() ? -1.0 : std::stod(sensitivityText);
            const fs::path spectralPath = resolveViewVisibilitySpectralPath(spectralText);
            if (!spectralPath.empty()) {
                opts.spectralEmissionPath = spectralPath.string();
            }
            opts.detailMode =
                (viewVisibilityDetailCombo_ && viewVisibilityDetailCombo_->selected_index() == 1)
                    ? ViewVisibilitySummaryOptions::DetailMode::ContrastProxy
                    : ViewVisibilitySummaryOptions::DetailMode::HdrvdpSubset;
            opts.inputColor = selectedViewVisibilityInputColor();

            const ViewVisibilitySummaryResult coreResult = analyzeViewVisibilitySummary(opts);
            const fs::path tempResultPath = viewVisibilityTempResultPath();
            writeViewVisibilityResultHdr(tempResultPath.string(), coreResult);

            ViewVisibilityNativeResult result;
            result.viewSize = coreResult.viewSize;
            result.referenceTotal = coreResult.referenceTotal;
            result.visibilityTotal = coreResult.visibilityTotal;
            result.referenceBaseline = coreResult.referenceBaseline;
            result.visibilityRatio = coreResult.visibilityRatio;
            result.qualityScore = coreResult.qualityScore;
            result.detailLabel = coreResult.detailLabel;
            result.inputColor = coreResult.inputColor;
            result.resultPath = tempResultPath;
            viewVisibilityResult_ = result;

            setViewVisibilityStatusCaption(
                "View visibility result is ready. The final HDR map was written to cache and loaded on the canvas."
            );
            setViewVisibilitySummaryCaption(std::format(
                "View size: {:L}\nReference baseline: {:.6f}\nVisibility ratio: {:.6f}\nQuality: {:.3f}\nDetail: {}\nInput color: {}",
                viewVisibilityResult_->viewSize,
                viewVisibilityResult_->referenceBaseline,
                viewVisibilityResult_->visibilityRatio,
                viewVisibilityResult_->qualityScore,
                viewVisibilityResult_->detailLabel,
                viewVisibilityInputColorLabel()
            ));
            applyViewVisibilityResultDisplay(false);
            updateContextStripUi();
        } catch (const std::exception& e) {
            resetViewVisibilityResult();
            setViewVisibilityStatusCaption("View visibility summary failed.");
            setViewVisibilitySummaryCaption(
                std::string{"View size: --\nReference baseline: --\nVisibility ratio: --\nQuality: --\nInput color: --\n\nError: "} + e.what()
            );
        }
    }

