    struct ToneMappingPfsProviderValues {
        std::vector<std::string> parameters;
        std::vector<bool> toggles;
    };

    struct ToneMappingPfsRunState {
        std::mutex mutex;
        bool active = false;
    };

    native::EPfsToneMappingProvider selectedToneMappingProvider() const {
        const auto& specs = native::pfsToneMappingProviderSpecs();
        const int index = toneMappingProviderCombo_ ? toneMappingProviderCombo_->selected_index() : 0;
        if (index < 0 || index >= static_cast<int>(specs.size())) {
            return native::EPfsToneMappingProvider::NativeInteractive;
        }
        return specs[static_cast<size_t>(index)].provider;
    }

    bool usesNativeInteractiveToneMapping() const {
        return selectedToneMappingProvider() == native::EPfsToneMappingProvider::NativeInteractive;
    }

    ToneMappingPfsProviderValues& ensureToneMappingPfsValues(native::EPfsToneMappingProvider provider) {
        const auto& spec = native::pfsToneMappingProviderSpec(provider);
        auto [it, inserted] = toneMappingPfsValues_.try_emplace(provider);
        if (inserted || it->second.parameters.size() != spec.parameters.size()) {
            it->second.parameters.clear();
            it->second.parameters.reserve(spec.parameters.size());
            for (const auto& parameter : spec.parameters) {
                it->second.parameters.push_back(parameter.defaultValue);
            }
        }
        if (inserted || it->second.toggles.size() != spec.toggles.size()) {
            it->second.toggles.clear();
            it->second.toggles.reserve(spec.toggles.size());
            for (const auto& toggle : spec.toggles) {
                it->second.toggles.push_back(toggle.defaultValue);
            }
        }
        return it->second;
    }

    void saveToneMappingPfsValues(native::EPfsToneMappingProvider provider) {
        if (provider == native::EPfsToneMappingProvider::NativeInteractive) {
            return;
        }
        const auto& spec = native::pfsToneMappingProviderSpec(provider);
        auto& values = ensureToneMappingPfsValues(provider);
        for (size_t index = 0;
             index < spec.parameters.size() && index < toneMappingPfsParameterBoxes_.size();
             ++index) {
            if (toneMappingPfsParameterBoxes_[index]) {
                values.parameters[index] =
                    normalizedTextBoxValue(toneMappingPfsParameterBoxes_[index]->value());
            }
        }
        for (size_t index = 0;
             index < spec.toggles.size() && index < toneMappingPfsToggleChecks_.size();
             ++index) {
            if (toneMappingPfsToggleChecks_[index]) {
                values.toggles[index] = toneMappingPfsToggleChecks_[index]->checked();
            }
        }
    }

    bool toneMappingPfsRunActive() {
        std::lock_guard<std::mutex> lock{toneMappingPfsRunState_.mutex};
        return toneMappingPfsRunState_.active;
    }

    void configureToneMappingProviderUi() {
        const auto provider = selectedToneMappingProvider();
        const bool nativeMode = provider == native::EPfsToneMappingProvider::NativeInteractive;
        if (toneMappingNativePanel_) {
            toneMappingNativePanel_->set_visible(nativeMode);
        }
        if (toneMappingPfsPanel_) {
            toneMappingPfsPanel_->set_visible(!nativeMode);
        }
        for (auto& [tileProvider, tile] : toneMappingTiles_) {
            if (tile) {
                tile->setSelected(tileProvider == provider);
            }
        }

        if (nativeMode) {
            if (toneMappingProviderInfoLabel_) {
                toneMappingProviderInfoLabel_->set_caption(
                    kNativeToneDescription
                );
            }
            return;
        }

        const auto& spec = native::pfsToneMappingProviderSpec(provider);
        auto& values = ensureToneMappingPfsValues(provider);
        if (toneMappingProviderInfoLabel_) {
            toneMappingProviderInfoLabel_->set_caption(spec.description);
        }

        // Map the operator's parameters onto the basic slots (shown) and the advanced slots
        // (under "Advanced"). The mapped arrays stay indexed by the operator's own parameter
        // order, so saving and command building are unchanged.
        for (size_t slot = 0; slot < kMaxPfsToneMappingParameters; ++slot) {
            if (toneMappingPfsBasicRowSlots_[slot]) toneMappingPfsBasicRowSlots_[slot]->set_visible(false);
            if (toneMappingPfsAdvancedRowSlots_[slot]) toneMappingPfsAdvancedRowSlots_[slot]->set_visible(false);
            toneMappingPfsParameterRows_[slot] = nullptr;
            toneMappingPfsParameterLabels_[slot] = nullptr;
            toneMappingPfsParameterBoxes_[slot] = nullptr;
        }
        for (size_t slot = 0; slot < kMaxPfsToneMappingToggles; ++slot) {
            if (toneMappingPfsBasicToggleSlots_[slot]) toneMappingPfsBasicToggleSlots_[slot]->set_visible(false);
            if (toneMappingPfsAdvancedToggleSlots_[slot]) toneMappingPfsAdvancedToggleSlots_[slot]->set_visible(false);
            toneMappingPfsToggleChecks_[slot] = nullptr;
        }
        size_t basicSlot = 0;
        size_t advancedSlot = 0;
        size_t advancedCount = 0;
        for (size_t index = 0; index < spec.parameters.size() && index < kMaxPfsToneMappingParameters; ++index) {
            const auto& parameter = spec.parameters[index];
            const bool advanced = parameter.advanced;
            const size_t slot = advanced ? advancedSlot++ : basicSlot++;
            advancedCount += advanced ? 1 : 0;
            Widget* row = advanced ? toneMappingPfsAdvancedRowSlots_[slot] : toneMappingPfsBasicRowSlots_[slot];
            Label* label = advanced ? toneMappingPfsAdvancedLabelSlots_[slot] : toneMappingPfsBasicLabelSlots_[slot];
            TextBox* box = advanced ? toneMappingPfsAdvancedBoxSlots_[slot] : toneMappingPfsBasicBoxSlots_[slot];
            toneMappingPfsParameterRows_[index] = row;
            toneMappingPfsParameterLabels_[index] = label;
            toneMappingPfsParameterBoxes_[index] = box;
            if (row) {
                row->set_visible(true);
            }
            if (label) {
                label->set_caption(parameter.label);
                label->set_tooltip(parameter.tooltip);
            }
            if (box) {
                box->set_value(values.parameters[index]);
                box->set_placeholder(parameter.optional ? "Auto / omit" : parameter.defaultValue);
                box->set_tooltip(parameter.tooltip);
            }
        }
        size_t basicToggle = 0;
        size_t advancedToggle = 0;
        for (size_t index = 0; index < spec.toggles.size() && index < kMaxPfsToneMappingToggles; ++index) {
            const auto& toggleSpec = spec.toggles[index];
            const bool advanced = toggleSpec.advanced;
            CheckBox* check = advanced ? toneMappingPfsAdvancedToggleSlots_[advancedToggle++]
                                       : toneMappingPfsBasicToggleSlots_[basicToggle++];
            advancedCount += advanced ? 1 : 0;
            toneMappingPfsToggleChecks_[index] = check;
            if (check) {
                check->set_visible(true);
                check->set_caption(toggleSpec.label);
                check->set_checked(values.toggles[index]);
                check->set_tooltip(toggleSpec.tooltip);
            }
        }
        if (toneMappingAdvancedButton_) {
            toneMappingAdvancedButton_->set_visible(advancedCount > 0);
            toneMappingAdvancedButton_->set_caption(std::format("Advanced ({})", advancedCount));
        }
        if (toneMappingAdvancedBody_) {
            toneMappingAdvancedBody_->set_visible(
                advancedCount > 0 && toneMappingAdvancedButton_ && toneMappingAdvancedButton_->pushed()
            );
        }
        if (toneMappingPfsProviderVersionLabel_) {
            toneMappingPfsProviderVersionLabel_->set_caption(
                provider == native::EPfsToneMappingProvider::Ward97
                    ? spec.executable + " | bundled Radiance"
                    : spec.executable + " | installed pfstools 2.1.0 defaults"
            );
        }
        refreshToneMappingPresetUi();
    }

    enum class ToneMappingPresetKind { Default, Example, Custom };

    ToneMappingPresetKind currentToneMappingPresetKind() {
        const auto provider = selectedToneMappingProvider();
        if (provider == native::EPfsToneMappingProvider::NativeInteractive) {
            return ToneMappingPresetKind::Default;
        }
        const auto& spec = native::pfsToneMappingProviderSpec(provider);
        auto& values = ensureToneMappingPfsValues(provider);
        bool isDefault = true;
        bool isExample = !spec.exampleCommand.empty();
        for (size_t index = 0; index < spec.parameters.size() && index < values.parameters.size(); ++index) {
            const auto& parameter = spec.parameters[index];
            const std::string value = trim(values.parameters[index]);
            const std::string example = parameter.exampleValue.empty() ? parameter.defaultValue : parameter.exampleValue;
            isDefault = isDefault && value == parameter.defaultValue;
            isExample = isExample && value == example;
        }
        for (size_t index = 0; index < spec.toggles.size() && index < values.toggles.size(); ++index) {
            const auto& toggleSpec = spec.toggles[index];
            const bool example = toggleSpec.exampleValue < 0 ? toggleSpec.defaultValue : toggleSpec.exampleValue == 1;
            isDefault = isDefault && values.toggles[index] == toggleSpec.defaultValue;
            isExample = isExample && values.toggles[index] == example;
        }
        if (isExample) return ToneMappingPresetKind::Example;
        if (isDefault) return ToneMappingPresetKind::Default;
        return ToneMappingPresetKind::Custom;
    }

    void refreshToneMappingPresetUi() {
        const auto provider = selectedToneMappingProvider();
        if (provider == native::EPfsToneMappingProvider::NativeInteractive) {
            return;
        }
        const auto& spec = native::pfsToneMappingProviderSpec(provider);
        const auto kind = currentToneMappingPresetKind();
        const bool hasExample = !spec.exampleCommand.empty();
        if (toneMappingPresetDefaultButton_) {
            toneMappingPresetDefaultButton_->setSelected(kind == ToneMappingPresetKind::Default);
        }
        if (toneMappingPresetExampleButton_) {
            toneMappingPresetExampleButton_->setSelected(kind == ToneMappingPresetKind::Example);
            toneMappingPresetExampleButton_->set_enabled(hasExample && !toneMappingPfsRunActive());
        }
        if (toneMappingPresetNoteLabel_) {
            std::string note;
            if (kind == ToneMappingPresetKind::Example) {
                note = "Man page: " + spec.exampleCommand;
            } else if (kind == ToneMappingPresetKind::Default) {
                note = hasExample ? "Source-code defaults." : "Source-code defaults. The man page has no other example.";
            } else {
                note = "Custom values.";
            }
            toneMappingPresetNoteLabel_->set_caption(note);
        }
    }

    void applyToneMappingPreset(bool example) {
        const auto provider = selectedToneMappingProvider();
        if (provider == native::EPfsToneMappingProvider::NativeInteractive || toneMappingPfsRunActive()) {
            return;
        }
        const auto& spec = native::pfsToneMappingProviderSpec(provider);
        if (example && spec.exampleCommand.empty()) {
            return;
        }
        auto& values = ensureToneMappingPfsValues(provider);
        for (size_t index = 0; index < spec.parameters.size() && index < values.parameters.size(); ++index) {
            const auto& parameter = spec.parameters[index];
            values.parameters[index] =
                example && !parameter.exampleValue.empty() ? parameter.exampleValue : parameter.defaultValue;
        }
        for (size_t index = 0; index < spec.toggles.size() && index < values.toggles.size(); ++index) {
            const auto& toggleSpec = spec.toggles[index];
            values.toggles[index] =
                example && toggleSpec.exampleValue >= 0 ? toggleSpec.exampleValue == 1 : toggleSpec.defaultValue;
        }
        toneMappingPfsLastCommand_.clear();
        configureToneMappingProviderUi();
        refreshToneMappingUi();
        startToneMappingPfsRender(false);
    }

    // An operator tile selects the operator (through the hidden provider combo, so every
    // existing path sees the same selection) and immediately renders a preview.
    void selectToneMappingOperator(native::EPfsToneMappingProvider provider) {
        if (!toneMappingProviderCombo_ || toneMappingPfsRunActive()) {
            return;
        }
        const auto& specs = native::pfsToneMappingProviderSpecs();
        for (size_t index = 0; index < specs.size(); ++index) {
            if (specs[index].provider != provider) {
                continue;
            }
            if (toneMappingProviderCombo_->selected_index() != static_cast<int>(index)) {
                toneMappingProviderCombo_->set_selected_index(static_cast<int>(index));
                if (toneMappingProviderCombo_->callback()) {
                    toneMappingProviderCombo_->callback()(static_cast<int>(index));
                }
            }
            break;
        }
        startToneMappingPfsRender(false);
    }

    fs::path currentToneMappingPfsInputPath() const {
        if (!viewer_ || !viewer_->currentImage()) {
            return toneMappingPfsInputPath_;
        }
        const fs::path currentPath = viewer_->currentImage()->path();
        if (!toneMappingPfsOutputPath_.empty()) {
            std::error_code ec;
            const fs::path currentCanonical = fs::weakly_canonical(currentPath, ec);
            ec.clear();
            const fs::path outputCanonical = fs::weakly_canonical(toneMappingPfsOutputPath_, ec);
            if (!ec && currentCanonical == outputCanonical && !toneMappingPfsInputPath_.empty()) {
                return toneMappingPfsInputPath_;
            }
        }
        return currentPath;
    }

    fs::path toneMappingPfsCacheDirectory() const {
        if (const char* home = std::getenv("HOME"); home && *home) {
            return fs::path{home} / "Library/Caches/hdrspace/pfstmo";
        }
        return fs::temp_directory_path() / "hdrspace/pfstmo";
    }

    native::PfsToneMappingRequest currentToneMappingPfsRequest(const fs::path& outputPath) {
        const auto provider = selectedToneMappingProvider();
        saveToneMappingPfsValues(provider);
        auto& values = ensureToneMappingPfsValues(provider);

        native::PfsToneMappingRequest request;
        request.provider = provider;
        request.toolsDirectory = normalizedTextBoxValue(
            toneMappingPfsToolsBox_ ? toneMappingPfsToolsBox_->value() : ""
        );
        request.inputPath = currentToneMappingPfsInputPath();
        request.outputPath = outputPath;
        request.parameterValues = values.parameters;
        request.toggleValues = values.toggles;
        request.radianceAbsolute =
            toneMappingPfsRadianceAbsoluteCheck_ && toneMappingPfsRadianceAbsoluteCheck_->checked();
        request.previewWidth = toneMappingPfsForceFull_
            ? std::string("Full")
            : normalizedTextBoxValue(
                  toneMappingPfsPreviewWidthBox_ ? toneMappingPfsPreviewWidthBox_->value() : "Full"
              );
        request.radianceDirectory = paths_.radianceBinDir;
        return request;
    }

    std::string toneMappingPfsCacheKey(const native::PfsToneMappingRequest& request) const {
        std::ostringstream key;
        key << static_cast<int>(request.provider) << '\n'
            << request.inputPath.string() << '\n'
            << request.radianceAbsolute << '\n'
            << request.previewWidth << '\n';
        std::error_code ec;
        key << fs::file_size(request.inputPath, ec) << '\n';
        ec.clear();
        key << static_cast<long long>(
            fs::last_write_time(request.inputPath, ec).time_since_epoch().count()
        ) << '\n';
        for (const auto& value : request.parameterValues) {
            key << value << '\n';
        }
        for (bool value : request.toggleValues) {
            key << value << '\n';
        }
        return std::format("{:016x}", std::hash<std::string>{}(key.str()));
    }

    void showToneMappingPfsPreview(const fs::path& inputPath, const fs::path& outputPath) {
        toneMappingPfsInputPath_ = inputPath;
        toneMappingPfsOutputPath_ = outputPath;
        if (viewer_) {
            viewer_->setAiMaskPickMode(tev::ImageViewer::EAiMaskPickMode::None);
            viewer_->clearAiMaskPromptPoints();
            viewer_->setOffset(0.0f);
            viewer_->setExposure(0.0f);
            viewer_->setTonemap(tev::ETonemap::SRGB);
        }
        loadImageIntoViewer(outputPath);
        updateContextStripUi();
    }

    void startToneMappingPfsRender(bool fullSize = false) {
        toneMappingPfsForceFull_ = fullSize;
        const auto provider = selectedToneMappingProvider();
        if (provider == native::EPfsToneMappingProvider::NativeInteractive) {
            return;
        }
        if (toneMappingPfsRunActive()) {
            showMessage("A pfstools tone-mapping preview is already running.");
            return;
        }

        const fs::path inputPath = currentToneMappingPfsInputPath();
        if (inputPath.empty() || !fs::exists(inputPath)) {
            showMessage("Open a saved HDR image before rendering a pfstools preview.");
            return;
        }
        toneMappingPfsInputPath_ = inputPath;

        const auto& spec = native::pfsToneMappingProviderSpec(provider);
        fs::path cacheDirectory = toneMappingPfsCacheDirectory();
        std::error_code ec;
        fs::create_directories(cacheDirectory, ec);
        if (ec) {
            showMessage("Could not create the pfstools preview cache:\n" + ec.message());
            return;
        }

        native::PfsToneMappingRequest keyRequest = currentToneMappingPfsRequest({});
        const std::string key = toneMappingPfsCacheKey(keyRequest);
        const std::string stem = inputPath.stem().string();
        const fs::path outputPath =
            cacheDirectory / (stem + "-" + spec.slug + "-" + key + ".png");
        const fs::path temporaryPath =
            cacheDirectory / (stem + "-" + spec.slug + "-" + key + ".tmp.png");

        native::PfsToneMappingRequest request = currentToneMappingPfsRequest(temporaryPath);
        toneMappingPfsForceFull_ = false;
        const native::PfsToneMappingCommand command =
            native::buildPfsToneMappingCommand(request);
        if (!command.ok) {
            setToneMappingStatusCaption(command.error);
            showMessage("Could not prepare the pfstools preview:\n" + command.error);
            refreshToneMappingUi();
            return;
        }
        toneMappingPfsLastCommand_ = command.displayCommand;

        if (fs::exists(outputPath) && fs::file_size(outputPath, ec) > 0 && !ec) {
            setToneMappingStatusCaption(
                spec.label + " loaded from the hdrspace preview cache."
            );
            if (toneMappingPfsProgressBar_) {
                toneMappingPfsProgressBar_->set_value(1.0f);
            }
            showToneMappingPfsPreview(inputPath, outputPath);
            refreshToneMappingUi();
            return;
        }

        fs::remove(temporaryPath, ec);
        {
            std::lock_guard<std::mutex> lock{toneMappingPfsRunState_.mutex};
            toneMappingPfsRunState_.active = true;
        }
        const std::string previewWidthLower = tev::toLower(request.previewWidth);
        const std::string resolutionLabel =
            request.previewWidth.empty() || previewWidthLower == "full"
            ? "full resolution"
            : request.previewWidth + " px";
        setToneMappingStatusCaption(
            spec.label + " is rendering at " + resolutionLabel + "..."
        );
        if (toneMappingPfsProgressBar_) {
            toneMappingPfsProgressBar_->set_value(0.12f);
        }
        refreshToneMappingUi();

        std::thread([
            this,
            inputPath,
            outputPath,
            temporaryPath,
            provider,
            command
        ] {
            ProcessResult process;
            std::string errorText;
            std::string providerWarning;
            bool success = false;
            try {
                process = runShellCommandWithCapturedOutput(command.command);
                std::error_code fileError;
                success =
                    process.exitCode == 0 &&
                    fs::exists(temporaryPath) &&
                    fs::file_size(temporaryPath, fileError) > 0 &&
                    !fileError;
                if (success) {
                    fs::rename(temporaryPath, outputPath, fileError);
                    if (fileError) {
                        fileError.clear();
                        fs::copy_file(
                            temporaryPath,
                            outputPath,
                            fs::copy_options::overwrite_existing,
                            fileError
                        );
                        if (!fileError) {
                            fs::remove(temporaryPath, fileError);
                        }
                    }
                    success = !fileError && fs::exists(outputPath);
                }
                if (success) {
                    const size_t warningStart = process.stderrText.find("Warning:");
                    if (warningStart != std::string::npos) {
                        const size_t warningEnd = process.stderrText.find('\n', warningStart);
                        providerWarning = process.stderrText.substr(
                            warningStart,
                            warningEnd == std::string::npos
                                ? std::string::npos
                                : warningEnd - warningStart
                        );
                    }
                }
                if (!success) {
                    errorText = process.stderrText.empty()
                        ? process.stdoutText
                        : process.stderrText;
                    if (errorText.empty()) {
                        errorText = "pfstools did not create a preview image.";
                    }
                }
            } catch (const std::exception& e) {
                errorText = e.what();
            }
            if (errorText.size() > 1800) {
                errorText = "...\n" + errorText.substr(errorText.size() - 1800);
            }

            viewer_->scheduleToUiThread([
                this,
                inputPath,
                outputPath,
                provider,
                success,
                providerWarning = std::move(providerWarning),
                errorText = std::move(errorText)
            ] {
                {
                    std::lock_guard<std::mutex> lock{toneMappingPfsRunState_.mutex};
                    toneMappingPfsRunState_.active = false;
                }
                if (!success) {
                    if (toneMappingPfsProgressBar_) {
                        toneMappingPfsProgressBar_->set_value(0.0f);
                    }
                    setToneMappingStatusCaption("pfstools preview failed.");
                    refreshToneMappingUi();
                    showMessage("pfstools tone mapping failed:\n" + errorText);
                    return;
                }

                if (toneMappingPfsProgressBar_) {
                    toneMappingPfsProgressBar_->set_value(1.0f);
                }
                setToneMappingStatusCaption(
                    native::pfsToneMappingProviderSpec(provider).label +
                    (providerWarning.empty()
                        ? " preview ready: "
                        : " preview ready with provider warning: ") +
                    (providerWarning.empty()
                        ? outputPath.filename().string()
                        : providerWarning)
                );
                showToneMappingPfsPreview(inputPath, outputPath);
                refreshToneMappingUi();
            });
        }).detach();
    }

    void restoreToneMappingPfsInput() {
        if (toneMappingPfsInputPath_.empty() || !fs::exists(toneMappingPfsInputPath_)) {
            showMessage("The original pfstools input is not available.");
            return;
        }
        if (viewer_) {
            viewer_->setOffset(0.0f);
            viewer_->setExposure(0.0f);
            viewer_->setTonemap(tev::ETonemap::SRGB);
        }
        loadImageIntoViewer(toneMappingPfsInputPath_);
        setToneMappingStatusCaption(
            "Restored source HDR: " + toneMappingPfsInputPath_.filename().string()
        );
        configureToneMappingProviderUi();
        refreshToneMappingUi();
    }

    void copyToneMappingPfsCommand() {
        if (!viewer_ || toneMappingPfsLastCommand_.empty()) {
            return;
        }
        glfwSetClipboardString(viewer_->glfw_window(), toneMappingPfsLastCommand_.c_str());
        setToneMappingStatusCaption("Copied the exact pfstools pipeline to the clipboard.");
    }

    void setToneMappingStatusCaption(const std::string& caption) {
        if (toneMappingStatusLabel_) {
            toneMappingStatusLabel_->set_caption(caption);
        }
    }

    native::EGazeMeteringMode selectedToneMappingMeteringMode() const {
        const int index = toneMappingModeCombo_ ? toneMappingModeCombo_->selected_index() : 2;
        switch (index) {
        case 0: return native::EGazeMeteringMode::UniformAverage;
        case 1: return native::EGazeMeteringMode::CenterWeighted;
        default: return native::EGazeMeteringMode::GaussianGazeSpot;
        }
    }

    native::EGazeProjection selectedToneMappingProjection() const {
        const int index = toneMappingProjectionCombo_ ? toneMappingProjectionCombo_->selected_index() : 0;
        switch (index) {
        case 1: return native::EGazeProjection::AngularFisheye;
        case 2: return native::EGazeProjection::HemisphericalFisheye;
        case 3: return native::EGazeProjection::Perspective;
        default: return native::EGazeProjection::Auto;
        }
    }

    native::EGazeInputEncoding selectedToneMappingInputEncoding() const {
        const int index = toneMappingInputCombo_ ? toneMappingInputCombo_->selected_index() : 0;
        switch (index) {
        case 1: return native::EGazeInputEncoding::RadianceRgb;
        case 2: return native::EGazeInputEncoding::RadianceXyze;
        case 3: return native::EGazeInputEncoding::LinearRec709Rgb;
        case 4: return native::EGazeInputEncoding::SrgbEncodedRgb;
        case 5: return native::EGazeInputEncoding::CieXyz;
        case 6: return native::EGazeInputEncoding::LuminanceY;
        default: return native::EGazeInputEncoding::Auto;
        }
    }

    std::optional<double> toneMappingLuminanceScaleOverride() const {
        if (!toneMappingLuminanceScaleBox_) {
            return std::nullopt;
        }
        const std::string text = tev::toLower(normalizedTextBoxValue(toneMappingLuminanceScaleBox_->value()));
        if (text.empty() || text == "auto") {
            return std::nullopt;
        }
        double value = std::numeric_limits<double>::quiet_NaN();
        tryParseFloating(text, value);
        return value;
    }

    double toneMappingTextValue(const TextBox* box, double fallback, double minimum, double maximum) const {
        if (!box) {
            return fallback;
        }
        double value = fallback;
        if (!tryParseFloating(normalizedTextBoxValue(box->value()), value) || !std::isfinite(value)) {
            return fallback;
        }
        return std::clamp(value, minimum, maximum);
    }

    void markToneMappingDisplayProfileCustom() {
        if (toneMappingDisplayProfileCombo_) {
            toneMappingDisplayProfileCombo_->set_selected_index(
                static_cast<int>(kToneMappingDisplayProfiles.size() - 1)
            );
        }
    }

    void applyToneMappingDisplayProfile(int index) {
        if (index < 0 || index >= static_cast<int>(kToneMappingDisplayProfiles.size())) {
            return;
        }
        const auto& profile = kToneMappingDisplayProfiles[static_cast<size_t>(index)];
        if (toneMappingDisplayWidthBox_) {
            toneMappingDisplayWidthBox_->set_value(std::to_string(profile.pixelWidth));
        }
        if (toneMappingDisplayHeightBox_) {
            toneMappingDisplayHeightBox_->set_value(std::to_string(profile.pixelHeight));
        }
        if (toneMappingDisplayPpiBox_) {
            toneMappingDisplayPpiBox_->set_value(std::format("{:.1f}", profile.pixelsPerInch));
        }
        if (toneMappingViewingDistanceBox_) {
            toneMappingViewingDistanceBox_->set_value(std::format("{:.1f}", profile.viewingDistanceCm));
        }
        if (toneMappingReferenceWhiteBox_) {
            toneMappingReferenceWhiteBox_->set_value(std::format("{:.1f}", profile.referenceWhiteNits));
        }
        if (toneMappingPeakNitsBox_) {
            toneMappingPeakNitsBox_->set_value(std::format("{:.1f}", profile.peakNits));
        }
    }

    native::GazeDisplayGeometry toneMappingDisplayGeometry() const {
        native::GazeDisplayGeometry geometry;
        geometry.pixelWidth = static_cast<int>(std::lround(
            toneMappingTextValue(toneMappingDisplayWidthBox_, 3024.0, 320.0, 16384.0)
        ));
        geometry.pixelHeight = static_cast<int>(std::lround(
            toneMappingTextValue(toneMappingDisplayHeightBox_, 1964.0, 240.0, 16384.0)
        ));
        geometry.pixelsPerInch = toneMappingTextValue(toneMappingDisplayPpiBox_, 254.0, 20.0, 1000.0);
        geometry.viewingDistanceMm =
            10.0 * toneMappingTextValue(toneMappingViewingDistanceBox_, 50.0, 10.0, 500.0);
        geometry.enabled =
            toneMappingUseDisplayGeometryCheck_ && toneMappingUseDisplayGeometryCheck_->checked();
        return geometry;
    }

    double toneMappingReferenceWhiteNits() const {
        return toneMappingTextValue(toneMappingReferenceWhiteBox_, 80.0, 1.0, 10000.0);
    }

    double toneMappingPeakNits() const {
        return toneMappingTextValue(toneMappingPeakNitsBox_, 1600.0, 1.0, 10000.0);
    }

    void applyToneMappingDisplayProfileToViewer() {
        if (!viewer_ || !toneMappingApplyReferenceWhiteCheck_ ||
            !toneMappingApplyReferenceWhiteCheck_->checked()) {
            return;
        }
        viewer_->setDisplayWhiteLevelSetting(tev::ImageViewer::EDisplayWhiteLevelSetting::Custom);
        viewer_->setDisplayWhiteLevel(static_cast<float>(toneMappingReferenceWhiteNits()));
    }

    void updateToneMappingDisplayProfileInfo() {
        if (!toneMappingDisplayProfileInfoLabel_) {
            return;
        }
        const auto geometry = toneMappingDisplayGeometry();
        const double referenceWhite = toneMappingReferenceWhiteNits();
        const double peak = toneMappingPeakNits();
        const double headroom = peak / std::max(1e-6, referenceWhite);
        const double targetMid = referenceWhite *
            toneMappingTextValue(toneMappingTargetGreyBox_, 0.18, 0.01, 0.9);
        toneMappingDisplayProfileInfoLabel_->set_caption(std::format(
            "{} x {} px | {:.0f} ppi | {:.0f} cm\n"
            "Reference white {:.0f} nit | peak {:.0f} nit ({:.1f}x)\n"
            "Target grey on display: {:.1f} nit",
            geometry.pixelWidth,
            geometry.pixelHeight,
            geometry.pixelsPerInch,
            geometry.viewingDistanceMm / 10.0,
            referenceWhite,
            peak,
            headroom,
            targetMid
        ));
    }

    void applyToneMappingDisplayMode() {
        if (!viewer_) {
            return;
        }
        applyToneMappingDisplayProfileToViewer();
        const int mode = toneMappingOutputCombo_ ? toneMappingOutputCombo_->selected_index() : 0;
        switch (mode) {
        case 1: viewer_->setTonemap(tev::ETonemap::Reinhard); break;
        case 2: viewer_->setTonemap(tev::ETonemap::SRGB); break;
        case 3: viewer_->setTonemap(tev::ETonemap::Gamma); break;
        default: break;
        }
        updateContextStripUi();
    }

    native::EGazeOutputMapping toneMappingHighlightOutputMapping() const {
        const int mode = toneMappingOutputCombo_ ? toneMappingOutputCombo_->selected_index() : 0;
        const tev::ETonemap effectiveTonemap =
            mode == 1 ? tev::ETonemap::Reinhard :
            mode == 2 ? tev::ETonemap::SRGB :
            mode == 3 ? tev::ETonemap::Gamma :
            viewer_ ? viewer_->tonemap() : tev::ETonemap::SRGB;
        return effectiveTonemap == tev::ETonemap::Reinhard
            ? native::EGazeOutputMapping::Reinhard
            : native::EGazeOutputMapping::Clipping;
    }

    void updateToneMappingMarker() {
        if (!viewer_ || activeRightPlane_ != RightPlane::ToneMapping) {
            return;
        }
        if (usesNativeInteractiveToneMapping() &&
            selectedToneMappingMeteringMode() == native::EGazeMeteringMode::GaussianGazeSpot &&
            toneMappingGazePoint_.has_value()) {
            viewer_->setAiMaskPromptPoints({*toneMappingGazePoint_}, {});
        } else {
            viewer_->clearAiMaskPromptPoints();
        }
    }

