    native::ImageStatisticsGraph toneMappingLuminanceDistributionGraph(bool cleanExport) const {
        native::ImageStatisticsGraph graph;
        if (!cleanExport) {
            graph.title = "Left-eye luminance quantile";
            graph.subtitle = "Black fisheye corners are excluded";
            graph.xLabel = "Pixel quantile (0-1)";
            graph.yLabel = toneMappingDistributionResult_.has_value() &&
                    toneMappingDistributionResult_->luminance.absoluteLuminance
                ? "cd/m²"
                : "relative Y";
        }
        if (!toneMappingDistributionResult_.has_value() ||
            !toneMappingDistributionResult_->ok) {
            return graph;
        }

        tev::ProfileGraphSeries series;
        series.label = "L";
        series.color = cleanExport
            ? Color(20, 24, 31, 255)
            : Color(255, 209, 84, 255);
        series.x = toneMappingDistributionResult_->quantile;
        series.y = toneMappingDistributionResult_->luminanceAtQuantile;
        graph.series.push_back(std::move(series));
        return graph;
    }

    static double toneMappingDistributionQuantile(
        const native::LuminanceDistributionResult& result,
        double quantile
    ) {
        if (result.quantile.empty() ||
            result.quantile.size() != result.luminanceAtQuantile.size()) {
            return 0.0;
        }
        const float q = static_cast<float>(std::clamp(quantile, 0.0, 1.0));
        const auto upper = std::lower_bound(
            result.quantile.begin(),
            result.quantile.end(),
            q
        );
        if (upper == result.quantile.begin()) {
            return result.luminanceAtQuantile.front();
        }
        if (upper == result.quantile.end()) {
            return result.luminanceAtQuantile.back();
        }
        const size_t upperIndex = static_cast<size_t>(
            upper - result.quantile.begin()
        );
        const size_t lowerIndex = upperIndex - 1;
        const double q0 = result.quantile[lowerIndex];
        const double q1 = result.quantile[upperIndex];
        const double blend = q1 > q0
            ? (static_cast<double>(q) - q0) / (q1 - q0)
            : 0.0;
        return
            static_cast<double>(result.luminanceAtQuantile[lowerIndex]) *
                (1.0 - blend) +
            static_cast<double>(result.luminanceAtQuantile[upperIndex]) *
                blend;
    }

    static double toneMappingDistributionThresholdFraction(
        const native::LuminanceDistributionResult& result,
        double threshold
    ) {
        const auto found = std::ranges::find_if(
            result.thresholds,
            [threshold](const auto& item) {
                return std::abs(item.luminance - threshold) < 1e-9;
            }
        );
        return found == result.thresholds.end()
            ? 0.0
            : found->fractionAtOrAbove;
    }

    static double toneMappingDistributionTailShare(
        const native::LuminanceDistributionResult& result,
        double topFraction
    ) {
        const auto found = std::ranges::find_if(
            result.tails,
            [topFraction](const auto& item) {
                return std::abs(item.topFraction - topFraction) < 1e-9;
            }
        );
        return found == result.tails.end()
            ? 0.0
            : found->luminanceSumFraction;
    }

    void refreshToneMappingLuminanceDistributionUi() {
        const bool hasImage = viewer_ && viewer_->currentImage();
        if (toneMappingDistributionComputeButton_) {
            toneMappingDistributionComputeButton_->set_enabled(hasImage);
        }
        if (toneMappingDistributionSaveButton_) {
            toneMappingDistributionSaveButton_->set_enabled(
                hasImage &&
                toneMappingDistributionResult_.has_value() &&
                toneMappingDistributionResult_->ok
            );
        }

        if (!toneMappingDistributionResult_.has_value() ||
            !toneMappingDistributionResult_->ok) {
            if (toneMappingDistributionGraph_) {
                applyProfileGraph(
                    toneMappingDistributionGraph_,
                    std::nullopt,
                    tev::EProfileGraphDisplayMode::Line
                );
            }
            if (toneMappingDistributionSummaryLabel_) {
                toneMappingDistributionSummaryLabel_->set_caption(
                    hasImage
                        ? "Compute uses the original linear HDR. A 2:1 dual fisheye is "
                          "automatically cropped to its left 180° eye."
                        : "Open a linear HDR image first."
                );
            }
            return;
        }

        const auto& result = *toneMappingDistributionResult_;
        if (toneMappingDistributionGraph_) {
            auto graph = toneMappingLuminanceDistributionGraph(false);
            applyProfileGraph(
                toneMappingDistributionGraph_,
                graph,
                tev::EProfileGraphDisplayMode::Line
            );
        }
        if (toneMappingDistributionSummaryLabel_) {
            const std::string unit = result.luminance.absoluteLuminance
                ? "cd/m²"
                : "relative Y";
            toneMappingDistributionSummaryLabel_->set_caption(std::format(
                "{} | {:L} px | max {:.6g} {}\n"
                "P98 {:.5g} | P99 {:.5g} | P99.9 {:.5g}\n"
                "≥100: {:.4g}% | ≥500: {:.4g}% | ≥10,000: {:.4g}%\n"
                "Top 0.1% carries {:.4g}% of summed luminance.",
                result.croppedLeftEye ? "Left 180° eye" : "Current image",
                result.pixelCount,
                result.maximumLuminance,
                unit,
                toneMappingDistributionQuantile(result, 0.98),
                toneMappingDistributionQuantile(result, 0.99),
                toneMappingDistributionQuantile(result, 0.999),
                100.0 * toneMappingDistributionThresholdFraction(result, 100.0),
                100.0 * toneMappingDistributionThresholdFraction(result, 500.0),
                100.0 * toneMappingDistributionThresholdFraction(result, 10000.0),
                100.0 * toneMappingDistributionTailShare(result, 0.001)
            ));
        }
    }

    void computeToneMappingLuminanceDistribution() {
        if (!viewer_ || !viewer_->currentImage() || !viewer_->imageCanvas()) {
            toneMappingDistributionResult_.reset();
            refreshToneMappingLuminanceDistributionUi();
            return;
        }

        setToneMappingStatusCaption(
            "Computing full-resolution left-eye luminance distribution..."
        );
        native::GazeLuminanceSettings luminanceSettings;
        luminanceSettings.encoding = selectedToneMappingInputEncoding();
        luminanceSettings.scaleOverride = toneMappingLuminanceScaleOverride();
        toneMappingDistributionResult_ = native::computeLuminanceDistribution(
            *viewer_->currentImage(),
            viewer_->imageCanvas()->requestedChannelGroup(),
            selectedToneMappingProjection(),
            luminanceSettings
        );
        toneMappingDistributionImageId_ = viewer_->currentImage()->id();
        toneMappingDistributionDirty_ = false;

        setToneMappingStatusCaption(toneMappingDistributionResult_->statusMessage);
        refreshToneMappingLuminanceDistributionUi();
        refreshToneMappingUi();
        if (viewer_) {
            viewer_->perform_layout(viewer_->nvg_context());
            viewer_->redraw();
        }
    }

    fs::path suggestedToneMappingDistributionPngPath() const {
        if (!viewer_ || !viewer_->currentImage()) {
            return safeCurrentPath() / "luminance_quantile_clean.png";
        }
        const fs::path imagePath = viewer_->currentImage()->path();
        const fs::path directory = imagePath.empty()
            ? safeCurrentPath()
            : imagePath.parent_path();
        const std::string stem = imagePath.empty()
            ? "image"
            : sanitizeStem(imagePath);
        return directory / (stem + "_left180_luminance_quantile_clean.png");
    }

    void saveToneMappingLuminanceDistributionPng() {
        if (!viewer_ || !viewer_->currentImage()) {
            showMessage("Open a linear HDR image first.");
            return;
        }
        if (toneMappingDistributionDirty_ ||
            toneMappingDistributionImageId_ != viewer_->currentImage()->id() ||
            !toneMappingDistributionResult_.has_value() ||
            !toneMappingDistributionResult_->ok) {
            computeToneMappingLuminanceDistribution();
        }
        if (!toneMappingDistributionResult_.has_value() ||
            !toneMappingDistributionResult_->ok) {
            showMessage("The luminance distribution could not be computed.");
            return;
        }

        try {
            std::vector<std::pair<std::string, std::string>> filters = {
                {"png", "PNG image"}
            };
            const auto chosen = file_dialog(
                viewer_,
                FileDialogType::Save,
                filters,
                suggestedToneMappingDistributionPngPath().string()
            );
            if (chosen.empty() || chosen.front().empty()) {
                return;
            }
            fs::path outputPath = chosen.front();
            if (tev::toLower(outputPath.extension().string()) != ".png") {
                outputPath += ".png";
            }
            fs::create_directories(outputPath.parent_path());

            auto graph = toneMappingLuminanceDistributionGraph(true);
            tev::ProfileGraphStyle style;
            style.backgroundColor = Color(255, 255, 255, 255);
            style.transparentBackground = false;
            style.xAxisFontSize = 18.0f;
            style.yAxisFontSize = 18.0f;
            style.titleFontSize = 1.0f;
            style.subtitleFontSize = 1.0f;
            style.xMinOverride = 0.0f;
            style.xMaxOverride = 1.0f;
            style.yMinOverride = 0.0f;
            style.xTickStep = 0.1f;
            const auto rgba = native::renderGraphPanelsToRgba(
                std::span<const native::ImageStatisticsGraph>{&graph, 1},
                native::EImageStatisticsGraphMode::Line,
                3200,
                1800,
                Color(255, 255, 255, 255),
                &style
            );
            if (rgba.empty()) {
                throw std::runtime_error(
                    "The luminance graph renderer returned no pixels."
                );
            }

            std::ofstream output(outputPath, std::ios::binary);
            if (!output) {
                throw std::runtime_error(
                    "Could not open the graph PNG for writing."
                );
            }
            tev::PngImageSaver saver;
            saver.save(output, outputPath, rgba, {3200, 1800}, 4).get();
            setToneMappingStatusCaption(
                "Saved clean luminance graph: " + outputPath.filename().string()
            );
        } catch (const std::exception& e) {
            showMessage(
                std::string("Failed to save luminance graph:\n") + e.what()
            );
        }
    }

