    static Color glareSourceColor(int index) {
        static const std::array<Color, 12> palette = {
            Color(255, 92, 92, 255),
            Color(96, 220, 120, 255),
            Color(97, 153, 255, 255),
            Color(255, 205, 82, 255),
            Color(217, 118, 255, 255),
            Color(67, 226, 221, 255),
            Color(255, 145, 84, 255),
            Color(165, 255, 115, 255),
            Color(255, 118, 183, 255),
            Color(131, 196, 255, 255),
            Color(255, 239, 125, 255),
            Color(194, 173, 255, 255),
        };
        return palette[static_cast<size_t>(index) % palette.size()];
    }

    std::optional<EvalGlareOptions> buildGlareOptions(std::string* error) const {
        if (!viewer_ || !viewer_->currentImage()) {
            if (error) *error = "Open an HDR image first.";
            return std::nullopt;
        }

        const fs::path imagePath = viewer_->currentImage()->path();
        if (imagePath.empty() || !fs::exists(imagePath)) {
            if (error) *error = "Current image needs to come from a saved HDR file.";
            return std::nullopt;
        }

        EvalGlareOptions opts;
        opts.detailed = true;
        opts.simple = !glareModeCombo_ || glareModeCombo_->selected_index() == 0;
        opts.inputPath = imagePath.string();
        const bool glareForceEnabled = glareForceCheck_ && glareForceCheck_->checked();
        const Vector2i glareImageSize = viewer_->currentImage()->size();
        if (!glareForceEnabled) {
            if (glareImageSize.x() != glareImageSize.y()) {
                if (error) {
                    *error = std::format(
                        "Evaluate Glare needs a square cropped equidistant HDR. Current image is {}x{}. Crop it first or enable Force (-f).",
                        glareImageSize.x(),
                        glareImageSize.y()
                    );
                }
                return std::nullopt;
            }

            const std::string projection = viewer_->currentProjectionLabel();
            if (projection != "equidistant") {
                if (error) {
                    *error = std::format(
                        "Evaluate Glare needs an equidistant HDR. Current projection is {}. Convert it first or enable Force (-f).",
                        projection.empty() ? "unknown" : projection
                    );
                }
                return std::nullopt;
            }
        }

        try {
            // An empty box is evalglare without -b (2000 cd/m², or 5 x task luminance with -t).
            const std::string text = normalizedTextBoxValue(glareThresholdBox_ ? glareThresholdBox_->value() : "");
            opts.lumThreshold = text.empty() ? 2000.0 : std::stod(text);
            opts.thresholdExplicit = !text.empty();
        } catch (...) {
            if (error) *error = "Threshold must be a valid number.";
            return std::nullopt;
        }
        try {
            // The box shows evalglare's default radius, 0.2 rad, rounded to 11.46°; keep it exact.
            const std::string text = normalizedTextBoxValue(glareRadiusBox_ ? glareRadiusBox_->value() : "");
            opts.maxAngle = text.empty() || text == "11.46" ? 0.2 : std::stod(text) * M_PI / 180.0;
        } catch (...) {
            if (error) *error = "Radius must be a valid number.";
            return std::nullopt;
        }
        try {
            const std::string text = normalizedTextBoxValue(glareBandBox_ ? glareBandBox_->value() : "");
            const double degrees = text.empty() ? 0.0 : std::stod(text);
            opts.bandAngle = degrees * M_PI / 180.0;
        } catch (...) {
            if (error) *error = "Band must be a valid number.";
            return std::nullopt;
        }
        try {
            const std::string taskAngleText = normalizedTextBoxValue(glareTaskAngleBox_ ? glareTaskAngleBox_->value() : "");
            if (!taskAngleText.empty()) {
                const std::string xText = normalizedTextBoxValue(glareTaskXBox_ ? glareTaskXBox_->value() : "");
                const std::string yText = normalizedTextBoxValue(glareTaskYBox_ ? glareTaskYBox_->value() : "");
                if (xText.empty() || yText.empty()) {
                    if (error) *error = "Task X and Task Y are required when task luminance is enabled.";
                    return std::nullopt;
                }
                opts.taskActive = true;
                opts.taskColor = glareTaskColorCheck_ && glareTaskColorCheck_->checked();
                opts.taskX = std::stoi(xText);
                opts.taskY = std::stoi(yText);
                opts.taskAngle = std::stod(taskAngleText) * M_PI / 180.0;
            } else if (glareTaskColorCheck_ && glareTaskColorCheck_->checked()) {
                if (error) *error = "Task color (-T) needs a task area.";
                return std::nullopt;
            }
        } catch (...) {
            if (error) *error = "Task center and angle must be valid numbers.";
            return std::nullopt;
        }
        try {
            const std::string splitText = normalizedTextBoxValue(glareSplitLimitBox_ ? glareSplitLimitBox_->value() : "");
            opts.splitLimit = splitText.empty() ? 50000.0 : std::stod(splitText);
        } catch (...) {
            if (error) *error = "Split limit must be a valid number.";
            return std::nullopt;
        }
        try {
            const std::string zone1Text = normalizedTextBoxValue(glareZone1Box_ ? glareZone1Box_->value() : "");
            const std::string zone2Text = normalizedTextBoxValue(glareZone2Box_ ? glareZone2Box_->value() : "");
            const bool hasZone1 = !zone1Text.empty();
            const bool hasZone2 = !zone2Text.empty();
            if (hasZone1 || hasZone2) {
                const std::string xText = normalizedTextBoxValue(glareZoneXBox_ ? glareZoneXBox_->value() : "");
                const std::string yText = normalizedTextBoxValue(glareZoneYBox_ ? glareZoneYBox_->value() : "");
                if (xText.empty() || yText.empty()) {
                    if (error) *error = "Zone X and Zone Y are required when zone analysis is enabled.";
                    return std::nullopt;
                }
                opts.zoneCenterX = std::stoi(xText);
                opts.zoneCenterY = std::stoi(yText);
                if (hasZone1) {
                    opts.zoneCount = 1;
                    opts.zoneAngle1 = std::stod(zone1Text) * M_PI / 180.0;
                }
                if (hasZone2) {
                    opts.zoneCount = 2;
                    opts.zoneAngle2 = std::stod(zone2Text) * M_PI / 180.0;
                }
            }
        } catch (...) {
            if (error) *error = "Zone center and angles must be valid numbers.";
            return std::nullopt;
        }

        const std::string maskPath = normalizedTextBoxValue(glareMaskBox_ ? glareMaskBox_->value() : "");
        if (!maskPath.empty()) {
            if (!fs::exists(maskPath)) {
                if (error) *error = "Mask HDR not found.";
                return std::nullopt;
            }
            opts.maskPath = maskPath;
        }

        if (opts.lumThreshold <= 0.0) {
            if (error) *error = "Threshold must be positive.";
            return std::nullopt;
        }
        if (opts.maxAngle <= 0.0) {
            if (error) *error = "Radius must be positive.";
            return std::nullopt;
        }
        if (opts.bandAngle < 0.0) {
            if (error) *error = "Band must be non-negative.";
            return std::nullopt;
        }
        if (opts.taskActive && opts.taskAngle <= 0.0) {
            if (error) *error = "Task angle must be positive.";
            return std::nullopt;
        }
        if (opts.splitLimit <= 0.0) {
            if (error) *error = "Split limit must be positive.";
            return std::nullopt;
        }
        if (opts.zoneCount > 0 && opts.zoneAngle1 <= 0.0) {
            if (error) *error = "Zone 1 angle must be positive.";
            return std::nullopt;
        }
        if (opts.zoneCount > 1 && opts.zoneAngle2 <= opts.zoneAngle1) {
            if (error) *error = "Zone 2 angle must be larger than Zone 1.";
            return std::nullopt;
        }

        opts.disableSplit = glareDisableSplitCheck_ && glareDisableSplitCheck_->checked();
        opts.force = glareForceEnabled;
        opts.localOnly = glareLocalOnlyCheck_ && glareLocalOnlyCheck_->checked();
        opts.equivLuminance = glareEqvLuminanceCheck_ && glareEqvLuminanceCheck_->checked();
        if (!opts.maskPath.empty() && opts.zoneCount > 0) {
            if (error) *error = "Masking and zoning cannot be activated at the same time.";
            return std::nullopt;
        }
        if (opts.localOnly && opts.zoneCount == 0 && opts.maskPath.empty()) {
            if (error) *error = "Local only (-lf) needs a mask or zone.";
            return std::nullopt;
        }
        opts.cutViewType = glareCutViewCombo_ ? glareCutViewCombo_->selected_index() : 0;

        return opts;
    }

    std::shared_ptr<tev::PixelBuffer> buildBandOverlayPixels(const EvalGlareAnalysisResult& result, double bandAngle) const {
        auto buffer = std::make_shared<tev::PixelBuffer>(tev::PixelBuffer::alloc(result.width * result.height * 4, tev::EPixelFormat::F32));
        auto* out = buffer->data<float>();
        std::fill(out, out + result.width * result.height * 4, 0.0f);

        if (bandAngle <= 0.0 || result.width == 0 || result.height == 0 ||
                result.bandAssignments.size() != result.width * result.height) {
            return buffer;
        }

        // The band pixels evalglare used (row 0 = bottom), shown top-down.
        for (size_t i = 0; i < result.bandAssignments.size(); ++i) {
            if (!result.bandAssignments[i]) {
                continue;
            }
            const size_t x = i % result.width;
            const size_t flippedY = result.height - 1 - i / result.width;
            const size_t idx = (flippedY * result.width + x) * 4;
            out[idx + 0] = 0.15f;
            out[idx + 1] = 0.95f;
            out[idx + 2] = 0.95f;
            out[idx + 3] = 0.72f;
        }

        return buffer;
    }

    std::shared_ptr<tev::PixelBuffer> buildZoneOverlayPixels(const EvalGlareAnalysisResult& result, int zoneId) const {
        auto buffer = std::make_shared<tev::PixelBuffer>(tev::PixelBuffer::alloc(result.width * result.height * 4, tev::EPixelFormat::F32));
        auto* out = buffer->data<float>();
        std::fill(out, out + result.width * result.height * 4, 0.0f);

        if (zoneId <= 0 || result.zoneAssignments.empty() || result.width == 0 || result.height == 0) {
            return buffer;
        }

        const Color color = zoneId == 1 ? Color(255, 220, 96, 255) : Color(255, 153, 92, 255);
        for (size_t i = 0; i < result.zoneAssignments.size(); ++i) {
            if (result.zoneAssignments[i] != zoneId) {
                continue;
            }
            const int x = static_cast<int>(i % result.width);
            const int y = static_cast<int>(i / result.width);
            const int flippedY = static_cast<int>(result.height) - 1 - y;
            const size_t idx = (static_cast<size_t>(flippedY) * result.width + static_cast<size_t>(x)) * 4;
            out[idx + 0] = color.r();
            out[idx + 1] = color.g();
            out[idx + 2] = color.b();
            out[idx + 3] = 0.70f;
        }

        return buffer;
    }

    void applyTaskOverlay(const EvalGlareAnalysisResult& result, float* out) const {
        if (!glareLastOptions_.has_value() || !glareLastOptions_->taskActive || !glareLastOptions_->taskColor) {
            return;
        }

        if (result.taskAssignments.size() != result.width * result.height) {
            return;
        }

        // The task-area pixels evalglare used (row 0 = bottom), shown top-down.
        for (size_t i = 0; i < result.taskAssignments.size(); ++i) {
            if (!result.taskAssignments[i]) {
                continue;
            }
            const size_t x = i % result.width;
            const size_t flippedY = result.height - 1 - i / result.width;
            const size_t idx = (flippedY * result.width + x) * 4;
            out[idx + 0] = std::max(out[idx + 0], 0.15f);
            out[idx + 1] = std::max(out[idx + 1], 0.25f);
            out[idx + 2] = std::max(out[idx + 2], 1.0f);
            out[idx + 3] = std::max(out[idx + 3], 0.48f);
        }
    }

    std::shared_ptr<tev::PixelBuffer> buildGlareOverlayPixels(const EvalGlareAnalysisResult& result, int selectedSource) const {
        if (selectedSource == kGlareBandSelection) {
            auto buffer = buildBandOverlayPixels(result, glareLastBandAngle_);
            applyTaskOverlay(result, buffer->data<float>());
            return buffer;
        }
        if (selectedSource == kGlareZone1Selection) {
            auto buffer = buildZoneOverlayPixels(result, 1);
            applyTaskOverlay(result, buffer->data<float>());
            return buffer;
        }
        if (selectedSource == kGlareZone2Selection) {
            auto buffer = buildZoneOverlayPixels(result, 2);
            applyTaskOverlay(result, buffer->data<float>());
            return buffer;
        }

        auto buffer = std::make_shared<tev::PixelBuffer>(tev::PixelBuffer::alloc(result.width * result.height * 4, tev::EPixelFormat::F32));
        auto* out = buffer->data<float>();
        std::fill(out, out + result.width * result.height * 4, 0.0f);

        for (size_t i = 0; i < result.sourceAssignments.size(); ++i) {
            const int sourceId = result.sourceAssignments[i];
            if (sourceId < 0 || sourceId >= static_cast<int>(result.sources.size())) {
                continue;
            }

            Color color = glareSourceColor(sourceId);
            float alpha = 0.78f;
            if (selectedSource >= 0) {
                if (sourceId == selectedSource) {
                    alpha = 1.0f;
                } else {
                    alpha = 0.12f;
                }
            }

            const int x = static_cast<int>(i % result.width);
            const int y = static_cast<int>(i / result.width);
            const int flippedY = static_cast<int>(result.height) - 1 - y;
            const size_t idx = (static_cast<size_t>(flippedY) * result.width + static_cast<size_t>(x)) * 4;
            out[idx + 0] = color.r();
            out[idx + 1] = color.g();
            out[idx + 2] = color.b();
            out[idx + 3] = alpha;
        }

        applyTaskOverlay(result, out);

        return buffer;
    }

    void updateGlareOverlay() {
        const bool wasUiVisible = viewer_ && viewer_->isUiVisible();
        if (!viewer_ || !viewer_->currentImage()) {
            if (viewer_) {
                viewer_->clearAnalysisOverlay();
                viewer_->setUiVisible(wasUiVisible);
                viewer_->redraw();
            }
            return;
        }

        if (activeRightPlane_ == RightPlane::AiSegmentation) {
            if (glareAiPreviewOverlayPixels_) {
                viewer_->setAnalysisOverlay(viewer_->currentImage(), glareAiPreviewOverlayPixels_);
            } else {
                viewer_->clearAnalysisOverlay();
            }
            viewer_->setUiVisible(wasUiVisible);
            viewer_->redraw();
            return;
        }

        if (activeRightPlane_ == RightPlane::ImageStatistics) {
            if (imageStatsResult_.has_value() && imageStatsResult_->overlayPixels) {
                viewer_->setAnalysisOverlay(viewer_->currentImage(), imageStatsResult_->overlayPixels);
            } else {
                viewer_->clearAnalysisOverlay();
            }
            viewer_->setUiVisible(wasUiVisible);
            viewer_->redraw();
            return;
        }

        if (activeRightPlane_ == RightPlane::Blur) {
            const fs::path imagePath = viewer_->currentImage()->path();
            const bool imageMatchesBlurSource =
                !imagePath.empty() &&
                !blurLiveImagePath_.empty() &&
                fs::weakly_canonical(imagePath) == fs::weakly_canonical(blurLiveImagePath_);
            if (blurHighlightCheck_ && blurHighlightCheck_->checked() && imageMatchesBlurSource && blurLivePreview_.overlayPixels) {
                viewer_->setAnalysisOverlay(viewer_->currentImage(), blurLivePreview_.overlayPixels);
            } else {
                viewer_->clearAnalysisOverlay();
            }
            viewer_->setUiVisible(wasUiVisible);
            viewer_->redraw();
            return;
        }

        if (activeRightPlane_ != RightPlane::EvaluateGlare) {
            viewer_->clearAnalysisOverlay();
            viewer_->setUiVisible(wasUiVisible);
            viewer_->redraw();
            return;
        }

        if (!glareResult_.has_value()) {
            viewer_->clearAnalysisOverlay();
            viewer_->setUiVisible(wasUiVisible);
            viewer_->redraw();
            return;
        }

        const fs::path imagePath = viewer_->currentImage()->path();
        if (imagePath.empty() || fs::weakly_canonical(imagePath) != fs::weakly_canonical(glareResultPath_)) {
            viewer_->clearAnalysisOverlay();
            viewer_->setUiVisible(wasUiVisible);
            viewer_->redraw();
            return;
        }

        if (viewer_->currentImage()->size().x() != static_cast<int>(glareResult_->width) ||
                viewer_->currentImage()->size().y() != static_cast<int>(glareResult_->height)) {
            viewer_->clearAnalysisOverlay();
            viewer_->setUiVisible(wasUiVisible);
            viewer_->redraw();
            return;
        }

        viewer_->setInspectionPresetIndex(5);
        viewer_->setDisplayInspectionInPreview(true);
        viewer_->setAnalysisOverlay(viewer_->currentImage(), buildGlareOverlayPixels(*glareResult_, glareSelectedSource_));
        viewer_->setUiVisible(wasUiVisible);
        viewer_->redraw();
    }

    void rebuildGlareSourceList() {
        if (!glareSourcesPanel_) {
            return;
        }

        glareSourceButtons_.clear();
        glareAllSourcesButton_ = nullptr;
        glareBandButton_ = nullptr;
        glareZone1Button_ = nullptr;
        glareZone2Button_ = nullptr;
        while (!glareSourcesPanel_->children().empty()) {
            glareSourcesPanel_->remove_child_at(glareSourcesPanel_->children().size() - 1);
        }

        if (!glareResult_.has_value()) {
            auto* empty = new Label(glareSourcesPanel_, "No glare result yet.", "sans", 12);
            empty->set_color(Color{214, 217, 220, 180});
            return;
        }

        glareAllSourcesButton_ = new InspectorTableRow(glareSourcesPanel_, hdrspaceInk(200), {},
            "All sources (" + std::to_string(glareResult_->sources.size()) + ")");
        glareAllSourcesButton_->set_callback([this] {
            glareSelectedSource_ = -1;
            updateGlareSourceSelectionUi();
            updateGlareOverlay();
            refreshGlareSelectionProfileUi();
            relayoutDesktopPanelsPreserveViewerUi();
        });

        if (glareResult_->hasBand && glareLastBandAngle_ > 0.0) {
            std::ostringstream caption;
            caption << "Band ±" << formatFloat(glareLastBandAngle_ * 180.0 / M_PI, 2)
                    << "°   Ω " << formatFloat(glareResult_->bandSolidAngle, 5)
                    << "   L " << formatFloat(glareResult_->bandAverageLuminance, 1);
            glareBandButton_ = new InspectorTableRow(glareSourcesPanel_, Color(100, 245, 245, 255), {}, caption.str());
            glareBandButton_->set_tooltip(
                "Band average luminance: " + formatFloat(glareResult_->bandAverageLuminance, 3) +
                "\nMedian luminance: " + formatFloat(glareResult_->bandMedianLuminance, 3) +
                "\nStd luminance: " + formatFloat(glareResult_->bandStdLuminance, 3) +
                "\n75th percentile: " + formatFloat(glareResult_->bandPercentile75, 3) +
                "\n95th percentile: " + formatFloat(glareResult_->bandPercentile95, 3) +
                "\nMin/Max: " + formatFloat(glareResult_->bandMinLuminance, 3) + " / " + formatFloat(glareResult_->bandMaxLuminance, 3)
            );
            glareBandButton_->set_callback([this] {
                glareSelectedSource_ = kGlareBandSelection;
                updateGlareSourceSelectionUi();
                updateGlareOverlay();
                refreshGlareSelectionProfileUi();
                relayoutDesktopPanelsPreserveViewerUi();
            });
        }

        auto makeZoneButton = [&](int zoneId, const EvalGlareZoneStats& zone, const std::string& caption) {
            auto* button = new InspectorTableRow(glareSourcesPanel_,
                zoneId == 1 ? Color(255, 220, 96, 255) : Color(255, 153, 92, 255), {}, caption);
            button->set_tooltip(
                "Average luminance: " + formatFloat(zone.averageLuminance, 3) +
                "\nMedian luminance: " + formatFloat(zone.medianLuminance, 3) +
                "\nVertical illuminance: " + formatFloat(zone.verticalIlluminance, 3) +
                "\nPixels: " + std::to_string(zone.pixelCount)
            );
            button->set_callback([this, zoneId] {
                glareSelectedSource_ = zoneId == 1 ? kGlareZone1Selection : kGlareZone2Selection;
                updateGlareSourceSelectionUi();
                updateGlareOverlay();
                refreshGlareSelectionProfileUi();
                relayoutDesktopPanelsPreserveViewerUi();
            });
            return button;
        };

        if (glareResult_->zoneCount > 0 && glareResult_->zone1.active) {
            std::ostringstream caption;
            caption << "Zone 1   Ω " << formatFloat(glareResult_->zone1.solidAngle, 5)
                    << "   L " << formatFloat(glareResult_->zone1.averageLuminance, 1);
            glareZone1Button_ = makeZoneButton(1, glareResult_->zone1, caption.str());
        } else {
            glareZone1Button_ = nullptr;
        }
        if (glareResult_->zoneCount > 1 && glareResult_->zone2.active) {
            std::ostringstream caption;
            caption << "Zone 2   Ω " << formatFloat(glareResult_->zone2.solidAngle, 5)
                    << "   L " << formatFloat(glareResult_->zone2.averageLuminance, 1);
            glareZone2Button_ = makeZoneButton(2, glareResult_->zone2, caption.str());
        } else {
            glareZone2Button_ = nullptr;
        }

        if (!glareResult_->sources.empty()) {
            new InspectorTableHeader(glareSourcesPanel_, {"#", "\u03a9 sr", "L cd/m\u00b2", "PI"});
        }
        for (size_t i = 0; i < glareResult_->sources.size(); ++i) {
            const auto& source = glareResult_->sources[i];
            std::string index = std::to_string(source.index);
            if (source.glareZone > 0) {
                index += " Z" + std::to_string(source.glareZone);
            }
            auto* button = new InspectorTableRow(glareSourcesPanel_, glareSourceColor(static_cast<int>(i)),
                {index, formatFloat(source.omega, 5), formatFloat(source.avgLum, 1), formatFloat(source.posIndex, 3)});
            button->set_tooltip(
                "Pixels: " + std::to_string(source.pixelCount) +
                "\nOmega: " + formatFloat(source.omega, 8) +
                "\nAverage luminance: " + formatFloat(source.avgLum, 3) +
                "\nPosition index: " + formatFloat(source.posIndex, 6)
            );
            button->set_callback([this, index = static_cast<int>(i)] {
                glareSelectedSource_ = index;
                updateGlareSourceSelectionUi();
                updateGlareOverlay();
                refreshGlareSelectionProfileUi();
                relayoutDesktopPanelsPreserveViewerUi();
            });
            glareSourceButtons_.push_back(button);
        }

        updateGlareSourceSelectionUi();
    }

    void updateGlareSourceSelectionUi() {
        if (glareAllSourcesButton_) {
            const bool selected = glareSelectedSource_ == -1;
            glareAllSourcesButton_->set_pushed(selected);
            glareAllSourcesButton_->set_background_color(Color(42, 56, 80, selected ? 165 : 110));
        }
        if (glareBandButton_) {
            const bool selected = glareSelectedSource_ == kGlareBandSelection;
            glareBandButton_->set_pushed(selected);
            glareBandButton_->set_background_color(Color(46, 92, 96, selected ? 165 : 78));
        }
        if (glareZone1Button_) {
            const bool selected = glareSelectedSource_ == kGlareZone1Selection;
            glareZone1Button_->set_pushed(selected);
            glareZone1Button_->set_background_color(Color(86, 74, 28, selected ? 165 : 78));
        }
        if (glareZone2Button_) {
            const bool selected = glareSelectedSource_ == kGlareZone2Selection;
            glareZone2Button_->set_pushed(selected);
            glareZone2Button_->set_background_color(Color(92, 62, 34, selected ? 165 : 78));
        }

        for (size_t i = 0; i < glareSourceButtons_.size(); ++i) {
            auto* button = glareSourceButtons_[i];
            if (!button) {
                continue;
            }

            const bool selected = glareSelectedSource_ == static_cast<int>(i);
            button->set_pushed(selected);
            const Color color = glareSourceColor(static_cast<int>(i));
            button->set_background_color(Color(
                static_cast<int>(color.r() * 255.0f),
                static_cast<int>(color.g() * 255.0f),
                static_cast<int>(color.b() * 255.0f),
                selected ? 110 : 42
            ));
        }
    }

    std::string currentAiPromptText() const {
        return normalizedTextBoxValue(glareAiPromptBox_ ? glareAiPromptBox_->value() : "");
    }

    void setAiStatusCaption(const std::string& caption) {
        if (aiSegStatusLabel_) {
            aiSegStatusLabel_->set_caption(caption);
        }
    }

    bool useResetTextAiPreview() const {
        return !currentAiPromptText().empty() && glareAiPositivePoints_.empty() && glareAiNegativePoints_.empty();
    }

    std::string currentAiRequestSignature() const {
        const bool resetTextMode = useResetTextAiPreview();
        std::ostringstream oss;
        oss << currentAiPreviewSignature()
            << "|prompt=" << currentAiPromptText()
            << "|fit=" << currentAiFitMode()
            << "|detail=" << currentAiPreviewMaxSide()
            << "|reset_text=" << (resetTextMode ? 1 : 0)
            << "|pos=";
        for (const auto& point : glareAiPositivePoints_) {
            oss << point.x() << "," << point.y() << ";";
        }
        oss << "|neg=";
        for (const auto& point : glareAiNegativePoints_) {
            oss << point.x() << "," << point.y() << ";";
        }
        return oss.str();
    }

    fs::path suggestedAiCandidateDirPath(uint64_t revision) const {
        if (!viewer_ || !viewer_->currentImage()) {
            return {};
        }
        const fs::path imagePath = viewer_->currentImage()->path();
        const std::string stem = imagePath.empty() ? sanitizeStem("ai_candidates") : sanitizeStem(imagePath);
        return paths_.cacheDir / (stem + "_ai_candidates_" + std::to_string(revision));
    }

    void clearAiCandidateMasks() {
        glareAiCandidates_.clear();
        glareAiCandidateButtons_.clear();
        glareAiCandidateSignature_.clear();
        glareAiPreviewOverlayPixels_.reset();
        refreshAiReviewSummaryUi();
    }

    bool hasSelectedAiCandidates() const {
        return std::any_of(glareAiCandidates_.begin(), glareAiCandidates_.end(), [](const auto& candidate) {
            return candidate.selected;
        });
    }

    std::shared_ptr<tev::PixelBuffer> buildSelectedAiCandidatePixels() const {
        if (!viewer_ || !viewer_->currentImage() || glareAiCandidates_.empty()) {
            return nullptr;
        }

        const Vector2i size = viewer_->currentImage()->size();
        const size_t width = static_cast<size_t>(size.x());
        const size_t height = static_cast<size_t>(size.y());
        auto combined = createBlankMaskPixels(width, height);
        auto* out = combined->data<float>();
        bool anySelected = false;

        for (const auto& candidate : glareAiCandidates_) {
            if (!candidate.selected || !candidate.pixels) {
                continue;
            }
            anySelected = true;
            const auto* src = candidate.pixels->data<float>();
            for (size_t i = 0; i < width * height; ++i) {
                if (src[i * 3] > 0.5f) {
                    out[i * 3 + 0] = 1.0f;
                    out[i * 3 + 1] = 1.0f;
                    out[i * 3 + 2] = 1.0f;
                }
            }
        }

        return anySelected ? combined : nullptr;
    }

    void updateAiCandidatePreviewOverlay() {
        auto combined = buildSelectedAiCandidatePixels();
        if (!combined) {
            glareAiPreviewOverlayPixels_ = nullptr;
        } else if (aiSegUsesColoredOverlay()) {
            glareAiPreviewOverlayPixels_ = buildAiColoredSegmentationOverlayPixels();
        } else {
            glareAiPreviewOverlayPixels_ = buildAiMaskOverlayPixels(combined);
        }
        updateGlareOverlay();
    }

    void updateAiCandidateSelectionUi() {
        for (size_t i = 0; i < glareAiCandidateButtons_.size() && i < glareAiCandidates_.size(); ++i) {
            auto* button = glareAiCandidateButtons_[i];
            if (!button) {
                continue;
            }
            const bool selected = glareAiCandidates_[i].selected;
            const auto color = aiCandidatePaletteColor(i);
            button->set_pushed(selected);
            button->set_background_color(Color(
                static_cast<int>(color.r()),
                static_cast<int>(color.g()),
                static_cast<int>(color.b()),
                selected ? 122 : 38
            ));
            button->set_text_color(selected ? Color(255, 255) : Color(238, 239, 240, 235));
        }
    }

    void rebuildAiCandidateList() {
        if (!glareAiCandidatesPanel_) {
            return;
        }

        glareAiCandidateButtons_.clear();
        while (!glareAiCandidatesPanel_->children().empty()) {
            glareAiCandidatesPanel_->remove_child_at(glareAiCandidatesPanel_->children().size() - 1);
        }

        if (glareAiCandidates_.empty()) {
            auto* empty = new Label(glareAiCandidatesPanel_, "No candidates yet.", "sans", 12);
            empty->set_color(Color(214, 217, 220, 180));
            if (glareAiCandidatesHintLabel_) {
                glareAiCandidatesHintLabel_->set_caption("No candidates yet.");
            }
            refreshAiReviewSummaryUi();
            return;
        }

        size_t selectedCount = 0;
        for (size_t i = 0; i < glareAiCandidates_.size(); ++i) {
            auto& candidate = glareAiCandidates_[i];
            selectedCount += candidate.selected ? 1 : 0;
            std::ostringstream caption;
            caption << "#" << (i + 1)
                    << "  " << (candidate.kind == "semantic" ? "[Sem]" : "[Inst]")
                    << "  ";
            if (candidate.kind == "instance") {
                caption << std::fixed << std::setprecision(2) << candidate.score << "  ";
            }
            caption << "px " << candidate.activePixels;
            auto* button = new Button(glareAiCandidatesPanel_, caption.str());
            button->set_font_size(13);
            button->set_flags(Button::ToggleButton);
            button->set_callback([this, index = static_cast<int>(i)] {
                if (index < 0 || index >= static_cast<int>(glareAiCandidates_.size())) {
                    return;
                }
                glareAiCandidates_[static_cast<size_t>(index)].selected = !glareAiCandidates_[static_cast<size_t>(index)].selected;
                updateAiCandidateSelectionUi();
                updateAiCandidatePreviewOverlay();
                updateAiMaskPointUi();
                relayoutDesktopPanelsPreserveViewerUi();
            });
            std::ostringstream tooltip;
            tooltip << candidate.path.filename().string();
            if (!candidate.promptVariant.empty()) {
                tooltip << "\nprompt: " << candidate.promptVariant;
            }
            if (candidate.kind == "instance") {
                tooltip << "\nscore: " << formatFloat(candidate.score, 4);
            }
            button->set_tooltip(tooltip.str());
            glareAiCandidateButtons_.push_back(button);
        }

        if (glareAiCandidatesHintLabel_) {
            glareAiCandidatesHintLabel_->set_caption(std::to_string(selectedCount) + "/" +
                                                    std::to_string(glareAiCandidates_.size()) + " selected");
        }
        refreshAiReviewSummaryUi();
        updateAiCandidateSelectionUi();
    }

    bool loadAiCandidatesFromDirectory(const fs::path& dirPath) {
        clearAiCandidateMasks();
        if (!viewer_ || !viewer_->currentImage() || dirPath.empty() || !fs::exists(dirPath)) {
            rebuildAiCandidateList();
            updateAiCandidatePreviewOverlay();
            return false;
        }

        struct CandidateMeta {
            std::string kind = "instance";
            double score = 0.0;
            size_t activePixels = 0;
            std::string promptVariant;
        };
        std::map<std::string, CandidateMeta> metadataByFilename;
        const fs::path metadataPath = dirPath / "candidates.tsv";
        if (fs::exists(metadataPath)) {
            std::istringstream metadataStream(readFile(metadataPath));
            std::string line;
            bool firstLine = true;
            while (std::getline(metadataStream, line)) {
                if (firstLine) {
                    firstLine = false;
                    continue;
                }
                if (line.empty()) {
                    continue;
                }
                const auto fields = splitTabFields(line);
                if (fields.size() < 5) {
                    continue;
                }
                CandidateMeta meta;
                meta.kind = trim(fields[1]);
                try {
                    meta.score = std::stod(fields[2]);
                } catch (...) {
                    meta.score = 0.0;
                }
                try {
                    meta.activePixels = static_cast<size_t>(std::stoull(fields[3]));
                } catch (...) {
                    meta.activePixels = 0;
                }
                meta.promptVariant = trim(fields[4]);
                metadataByFilename[trim(fields[0])] = meta;
            }
        }

        std::vector<fs::path> paths;
        for (const auto& entry : fs::directory_iterator{dirPath}) {
            if (!entry.is_regular_file()) {
                continue;
            }
            const std::string filename = entry.path().filename().string();
            if (filename.rfind("mask_", 0) != 0 || entry.path().extension() != ".png") {
                continue;
            }
            paths.push_back(entry.path());
        }
        std::sort(paths.begin(), paths.end());

        const Vector2i size = viewer_->currentImage()->size();
        for (const auto& path : paths) {
            auto pixels = loadBinaryMaskPngPixels(path, static_cast<size_t>(size.x()), static_cast<size_t>(size.y()));
            const auto* src = pixels->data<float>();
            size_t activePixels = 0;
            for (size_t i = 0; i < static_cast<size_t>(size.x()) * static_cast<size_t>(size.y()); ++i) {
                activePixels += src[i * 3] > 0.5f ? 1 : 0;
            }
            if (activePixels == 0) {
                continue;
            }
            AiCandidateMaskState candidate;
            candidate.path = path;
            candidate.pixels = pixels;
            candidate.selected = true;
            candidate.activePixels = activePixels;
            const auto metaIt = metadataByFilename.find(path.filename().string());
            if (metaIt != metadataByFilename.end()) {
                candidate.kind = metaIt->second.kind;
                candidate.score = metaIt->second.score;
                candidate.promptVariant = metaIt->second.promptVariant;
                if (metaIt->second.activePixels > 0) {
                    candidate.activePixels = metaIt->second.activePixels;
                }
            }
            glareAiCandidates_.push_back(std::move(candidate));
        }

        rebuildAiCandidateList();
        updateAiCandidatePreviewOverlay();
        return !glareAiCandidates_.empty();
    }

