    Vector2i currentAiPreviewOutputSize() const {
        if (!viewer_ || !viewer_->currentImage()) {
            return {0, 0};
        }

        const Vector2i fullSize = viewer_->currentImage()->size();
        int outWidth = fullSize.x();
        int outHeight = fullSize.y();
        const int previewMaxSide = currentAiPreviewMaxSide();
        const int maxSide = std::max(outWidth, outHeight);
        if (maxSide > previewMaxSide) {
            const double scale = static_cast<double>(previewMaxSide) / static_cast<double>(maxSide);
            outWidth = std::max(1, static_cast<int>(std::lround(outWidth * scale)));
            outHeight = std::max(1, static_cast<int>(std::lround(outHeight * scale)));
        }
        return {outWidth, outHeight};
    }

