    void applyProfileGraph(
        tev::ProfileGraph* graph,
        const std::optional<native::ImageStatisticsGraph>& data,
        tev::EProfileGraphDisplayMode displayMode
    ) {
        if (!graph) {
            return;
        }

        if (!data.has_value()) {
            graph->setTitle("No graph");
            graph->setSubtitle("");
            graph->setXAxisLabel("");
            graph->setYAxisLabel("");
            graph->clearSeries();
            graph->setDisplayMode(displayMode);
            return;
        }

        graph->setTitle(data->title);
        graph->setSubtitle(data->subtitle);
        graph->setXAxisLabel(data->xLabel);
        graph->setYAxisLabel(data->yLabel);
        graph->setSeries(data->series);
        graph->setDisplayMode(displayMode);
    }

    void applyImageStatisticsGraph(tev::ProfileGraph* graph, const std::optional<native::ImageStatisticsGraph>& data) {
        applyProfileGraph(graph, data, currentImageStatisticsProfileGraphMode());
    }

