    std::optional<GlareSelectionMaskState> buildCurrentGlareSelectionMask() const {
        if (!viewer_ || !viewer_->currentImage() || !glareResult_.has_value()) {
            return std::nullopt;
        }

        const int width = viewer_->currentImage()->size().x();
        const int height = viewer_->currentImage()->size().y();
        if (width <= 0 || height <= 0 ||
                static_cast<size_t>(width) != glareResult_->width ||
                static_cast<size_t>(height) != glareResult_->height) {
            return std::nullopt;
        }

        GlareSelectionMaskState state;
        state.mask.assign(static_cast<size_t>(width) * static_cast<size_t>(height), uint8_t{0});

        int minX = std::numeric_limits<int>::max();
        int minY = std::numeric_limits<int>::max();
        int maxX = std::numeric_limits<int>::min();
        int maxY = std::numeric_limits<int>::min();
        auto markTopLeftPixel = [&](int x, int y) {
            if (x < 0 || y < 0 || x >= width || y >= height) {
                return;
            }
            const size_t index = static_cast<size_t>(y) * static_cast<size_t>(width) + static_cast<size_t>(x);
            state.mask[index] = 255;
            minX = std::min(minX, x);
            minY = std::min(minY, y);
            maxX = std::max(maxX, x);
            maxY = std::max(maxY, y);
        };

        if (glareSelectedSource_ == kGlareBandSelection) {
            state.label = "Band";
            const double bandAngle = glareLastBandAngle_;
            if (bandAngle <= 0.0 || glareResult_->bandAssignments.empty()) {
                return std::nullopt;
            }

            for (size_t i = 0; i < glareResult_->bandAssignments.size(); ++i) {
                if (!glareResult_->bandAssignments[i]) {
                    continue;
                }
                const int x = static_cast<int>(i % glareResult_->width);
                const int internalY = static_cast<int>(i / glareResult_->width);
                markTopLeftPixel(x, height - 1 - internalY);
            }
        } else if (glareSelectedSource_ == kGlareZone1Selection || glareSelectedSource_ == kGlareZone2Selection) {
            const int zoneId = glareSelectedSource_ == kGlareZone1Selection ? 1 : 2;
            state.label = zoneId == 1 ? "Zone 1" : "Zone 2";
            if (glareResult_->zoneAssignments.empty()) {
                return std::nullopt;
            }
            for (size_t i = 0; i < glareResult_->zoneAssignments.size(); ++i) {
                if (glareResult_->zoneAssignments[i] != zoneId) {
                    continue;
                }
                const int x = static_cast<int>(i % glareResult_->width);
                const int internalY = static_cast<int>(i / glareResult_->width);
                markTopLeftPixel(x, height - 1 - internalY);
            }
        } else {
            if (glareResult_->sourceAssignments.empty()) {
                return std::nullopt;
            }
            if (glareSelectedSource_ >= 0 && glareSelectedSource_ < static_cast<int>(glareResult_->sources.size())) {
                const auto& source = glareResult_->sources[static_cast<size_t>(glareSelectedSource_)];
                std::ostringstream label;
                label << "Glare source #" << source.index;
                if (source.glareZone > 0) {
                    label << " [Z" << source.glareZone << "]";
                }
                state.label = label.str();
            } else {
                state.label = "All glare sources";
            }

            for (size_t i = 0; i < glareResult_->sourceAssignments.size(); ++i) {
                const int sourceId = glareResult_->sourceAssignments[i];
                if (sourceId < 0) {
                    continue;
                }
                if (glareSelectedSource_ >= 0 && sourceId != glareSelectedSource_) {
                    continue;
                }
                const int x = static_cast<int>(i % glareResult_->width);
                const int internalY = static_cast<int>(i / glareResult_->width);
                markTopLeftPixel(x, height - 1 - internalY);
            }
        }

        if (minX > maxX || minY > maxY) {
            return std::nullopt;
        }

        state.bounds = tev::Box2i{{minX, minY}, {maxX + 1, maxY + 1}};
        return state;
    }

    native::ImageStatisticsOptions currentGlareProfileOptions(const GlareSelectionMaskState& selection) const {
        native::ImageStatisticsOptions options;
        options.regionType = native::EImageStatisticsRegionType::SelectionMask;
        options.selectionMask = selection.mask;
        options.selectionBounds = selection.bounds;
        options.selectionLabel = selection.label;
        options.graphMode = native::EImageStatisticsGraphMode::LineScatter;

        if (glareProfileModeCombo_) {
            switch (glareProfileModeCombo_->selected_index()) {
                case 1: options.mode = native::EImageStatisticsMode::Horizontal; break;
                case 2: options.mode = native::EImageStatisticsMode::Vertical; break;
                default: options.mode = native::EImageStatisticsMode::Both; break;
            }
        }

        if (glareProfileValueCombo_ && glareProfileValueCombo_->selected_index() == 1 && glareProfileRgbSupported()) {
            options.valueMode = native::EImageStatisticsValueMode::RGB;
        } else {
            options.valueMode = native::EImageStatisticsValueMode::Luminance;
        }

        if (glareProfileAxisCombo_ && glareProfileAxisCombo_->selected_index() == 1) {
            options.axisMode = native::EImageStatisticsAxisMode::AngleDegrees;
        } else {
            options.axisMode = native::EImageStatisticsAxisMode::Pixels;
        }

        return options;
    }

    std::string currentGlareProfileSignature(const GlareSelectionMaskState& selection) const {
        std::ostringstream oss;
        oss << "sel=" << glareSelectedSource_
            << "|label=" << selection.label
            << "|mode=" << (glareProfileModeCombo_ ? glareProfileModeCombo_->selected_index() : 0)
            << "|value=" << (glareProfileValueCombo_ ? glareProfileValueCombo_->selected_index() : 0)
            << "|axis=" << (glareProfileAxisCombo_ ? glareProfileAxisCombo_->selected_index() : 0)
            << "|group=" << (viewer_ && viewer_->imageCanvas() ? viewer_->imageCanvas()->requestedChannelGroup() : std::string{})
            << "|ref=" << (viewer_ && viewer_->currentReference() ? static_cast<const void*>(viewer_->currentReference().get()) : nullptr)
            << "|text=" << glareResultText_.size();
        if (selection.bounds.has_value()) {
            const auto bounds = *selection.bounds;
            oss << "|bounds=" << bounds.min.x() << "," << bounds.min.y() << "," << bounds.max.x() << "," << bounds.max.y();
        }
        return oss.str();
    }

    void refreshGlareSelectionProfileUi() {
        if (glareProfileValueCombo_) {
            const bool rgbSupported = glareProfileRgbSupported();
            if (!rgbSupported && glareProfileValueCombo_->selected_index() != 0) {
                glareProfileValueCombo_->set_selected_index(0);
            }
            glareProfileValueCombo_->set_enabled(rgbSupported);
        }

        if (!viewer_ || !viewer_->currentImage()) {
            clearGlareSelectionProfileResult();
            if (glareProfileSummaryLabel_) {
                glareProfileSummaryLabel_->set_caption("Profile: open an image first");
            }
            if (glareProfileStatusLabel_) {
                glareProfileStatusLabel_->set_caption("No current image.");
            }
            return;
        }

        if (!glareResult_.has_value()) {
            clearGlareSelectionProfileResult();
            if (glareProfileSummaryLabel_) {
                glareProfileSummaryLabel_->set_caption("Profile: run Evaluate Glare first");
            }
            if (glareProfileStatusLabel_) {
                glareProfileStatusLabel_->set_caption("No glare result yet.");
            }
            return;
        }

        auto selection = buildCurrentGlareSelectionMask();
        if (!selection.has_value()) {
            clearGlareSelectionProfileResult();
            if (glareProfileSummaryLabel_) {
                glareProfileSummaryLabel_->set_caption("Profile: current selection is empty");
            }
            if (glareProfileStatusLabel_) {
                glareProfileStatusLabel_->set_caption("No valid glare pixels for this selection.");
            }
            return;
        }

        auto options = currentGlareProfileOptions(*selection);
        const std::string signature = currentGlareProfileSignature(*selection);
        if (glareProfileResult_.has_value() && glareProfileSignature_ == signature) {
            if (glareProfileSummaryLabel_) {
                glareProfileSummaryLabel_->set_caption(glareProfileResult_->regionSummary);
            }
            if (glareProfileStatusLabel_) {
                glareProfileStatusLabel_->set_caption(glareProfileResult_->statusMessage);
            }
            applyProfileGraph(glareProfileGraphA_, glareProfileResult_->graphs.empty() ? std::nullopt : std::optional{glareProfileResult_->graphs.front()}, currentGlareProfileGraphMode());
            if (glareProfileGraphBHost_) {
                glareProfileGraphBHost_->set_visible(glareProfileResult_->graphs.size() > 1);
            }
            applyProfileGraph(
                glareProfileGraphB_,
                glareProfileResult_->graphs.size() > 1 ? std::optional{glareProfileResult_->graphs[1]} : std::nullopt,
                currentGlareProfileGraphMode()
            );
            return;
        }

        try {
            const auto result = native::computeImageStatistics(*viewer_->currentImage(), *viewer_->imageCanvas(), viewer_->currentReference(), options);
            glareProfileResult_ = result;
            glareProfileSignature_ = signature;
            if (glareProfileSummaryLabel_) {
                glareProfileSummaryLabel_->set_caption(result.regionSummary.empty() ? ("Profile: " + selection->label) : result.regionSummary);
            }
            if (glareProfileStatusLabel_) {
                if (result.ok) {
                    glareProfileStatusLabel_->set_caption(result.statusMessage);
                } else {
                    glareProfileStatusLabel_->set_caption(result.statusMessage.empty() ? "Profile unavailable." : result.statusMessage);
                }
            }
            if (result.ok) {
                applyProfileGraph(glareProfileGraphA_, result.graphs.empty() ? std::nullopt : std::optional{result.graphs.front()}, currentGlareProfileGraphMode());
                if (glareProfileGraphBHost_) {
                    glareProfileGraphBHost_->set_visible(result.graphs.size() > 1);
                }
                applyProfileGraph(
                    glareProfileGraphB_,
                    result.graphs.size() > 1 ? std::optional{result.graphs[1]} : std::nullopt,
                    currentGlareProfileGraphMode()
                );
            } else {
                clearGlareSelectionProfileResult();
                if (glareProfileSummaryLabel_) {
                    glareProfileSummaryLabel_->set_caption("Profile: " + selection->label);
                }
                if (glareProfileStatusLabel_) {
                    glareProfileStatusLabel_->set_caption(result.statusMessage.empty() ? "Profile unavailable." : result.statusMessage);
                }
            }
        } catch (const std::exception& e) {
            clearGlareSelectionProfileResult();
            if (glareProfileSummaryLabel_) {
                glareProfileSummaryLabel_->set_caption("Profile: " + selection->label);
            }
            if (glareProfileStatusLabel_) {
                glareProfileStatusLabel_->set_caption(std::string("Profile failed: ") + e.what());
            }
        }

        if (graphPreviewWindow_ && graphPreviewWindow_->visible() && graphPreviewSource_ == GraphPreviewSource::EvaluateGlare) {
            requestGraphPreviewRefresh();
        }
    }

    void clearImageStatisticsResult() {
        imageStatsResult_.reset();
        imageStatsResultPath_.clear();
        applyImageStatisticsGraph(imageStatsGraphA_, std::nullopt);
        applyImageStatisticsGraph(imageStatsGraphB_, std::nullopt);
        if (imageStatsGraphBHost_) {
            imageStatsGraphBHost_->set_visible(false);
        }
        if (graphPreviewWindow_ && graphPreviewWindow_->visible() && graphPreviewSource_ == GraphPreviewSource::ImageStatistics) {
            graphPreviewDebugLog("requestGraphPreviewRefresh source=refreshImageStatisticsUi");
            requestGraphPreviewRefresh();
        }
    }

    void refreshImageStatisticsUi() {
        const bool hasImage = viewer_ && viewer_->currentImage();
        const auto pickMode = viewer_ ? viewer_->aiMaskPickMode() : tev::ImageViewer::EAiMaskPickMode::None;
        const bool circleMode = imageStatsRegionTypeCombo_ && imageStatsRegionTypeCombo_->selected_index() == 1;
        const bool rgbSupported = currentImageSupportsRgbStatistics();

        if (imageStatsValueModeCombo_) {
            imageStatsValueModeCombo_->set_enabled(hasImage);
            imageStatsValueModeCombo_->set_tooltip(
                rgbSupported
                    ? "Switch between luminance statistics and raw RGB channel statistics."
                    : "RGB can be selected, but this image may not expose three usable color channels."
            );
        }

        if (imageStatsCircleControlsPanel_) {
            imageStatsCircleControlsPanel_->set_visible(circleMode);
        }
        if (imageStatsPickCenterButton_) {
            imageStatsPickCenterButton_->set_enabled(hasImage && circleMode);
            imageStatsPickCenterButton_->set_pushed(pickMode == tev::ImageViewer::EAiMaskPickMode::StatsCenter);
        }
        if (imageStatsUseCurrentCenterButton_) {
            imageStatsUseCurrentCenterButton_->set_enabled(hasImage && circleMode);
        }
        if (imageStatsRefreshButton_) {
            imageStatsRefreshButton_->set_enabled(hasImage);
        }
        if (imageStatsSaveCsvButton_) {
            imageStatsSaveCsvButton_->set_enabled(imageStatsResult_.has_value() && imageStatsResult_->ok);
        }
        if (imageStatsSaveGraphButton_) {
            imageStatsSaveGraphButton_->set_enabled(imageStatsResult_.has_value() && imageStatsResult_->ok && !imageStatsResult_->graphs.empty());
        }
        if (imageStatsSaveRegionButton_) {
            imageStatsSaveRegionButton_->set_enabled(
                imageStatsResult_.has_value() &&
                imageStatsResult_->ok &&
                imageStatsResult_->selectionBounds.has_value() &&
                !imageStatsResult_->selectionMask.empty()
            );
        }
        if (imageStatsReloadButton_) {
            imageStatsReloadButton_->set_enabled(hasImage);
        }

        if (!hasImage) {
            if (imageStatsRegionSummaryLabel_) {
                imageStatsRegionSummaryLabel_->set_caption("Region: open an image first");
            }
            if (imageStatsAngularLabel_) {
                imageStatsAngularLabel_->set_caption("Angular axis: unavailable");
            }
            clearImageStatisticsResult();
            updateContextStripUi();
            return;
        }

        if (imageStatsResult_.has_value()) {
            const fs::path currentPath = viewer_->currentImage()->path();
            if (!imageStatsResultPath_.empty() && !currentPath.empty() && fs::weakly_canonical(currentPath) != fs::weakly_canonical(imageStatsResultPath_)) {
                clearImageStatisticsResult();
            }
        }

        const auto options = currentImageStatisticsOptions();
        if (options.regionType == native::EImageStatisticsRegionType::Rectangle) {
            const auto region = viewer_->imageCanvas()->statisticsRegionInImageCoords();
            if (region.isValid()) {
                imageStatsRegionSummaryLabel_->set_caption(std::format(
                    "Region: {} x {} px at {},{}",
                    region.size().x(),
                    region.size().y(),
                    region.min.x(),
                    region.min.y()
                ));
            } else {
                imageStatsRegionSummaryLabel_->set_caption("Region: current ROI/crop is empty");
            }
        } else {
            const std::string xText = normalizedTextBoxValue(imageStatsCircleXBox_ ? imageStatsCircleXBox_->value() : "");
            const std::string yText = normalizedTextBoxValue(imageStatsCircleYBox_ ? imageStatsCircleYBox_->value() : "");
            const std::string rText = normalizedTextBoxValue(imageStatsCircleRadiusBox_ ? imageStatsCircleRadiusBox_->value() : "");
            imageStatsRegionSummaryLabel_->set_caption(
                xText.empty() || yText.empty() || rText.empty()
                    ? "Region: set circle X, Y and R°"
                    : std::format("Region: center {},{} | radius {}°", xText, yText, rText)
            );
        }

        const std::string angularMessage = native::imageStatisticsAngularAxisMessage(*viewer_->currentImage());
        imageStatsAngularLabel_->set_caption(
            angularMessage.empty()
                ? "Angular axis: available"
                : "Angular axis: " + angularMessage
        );

        if (imageStatsResult_.has_value() && imageStatsResult_->ok) {
            applyImageStatisticsGraph(imageStatsGraphA_, imageStatsResult_->graphs.empty() ? std::nullopt : std::optional{imageStatsResult_->graphs.front()});
            if (imageStatsGraphBHost_) {
                imageStatsGraphBHost_->set_visible(imageStatsResult_->graphs.size() > 1);
            }
            applyImageStatisticsGraph(
                imageStatsGraphB_,
                imageStatsResult_->graphs.size() > 1 ? std::optional{imageStatsResult_->graphs[1]} : std::nullopt
            );
        } else {
            applyImageStatisticsGraph(imageStatsGraphA_, std::nullopt);
            applyImageStatisticsGraph(imageStatsGraphB_, std::nullopt);
            if (imageStatsGraphBHost_) {
                imageStatsGraphBHost_->set_visible(false);
            }
        }

        if (graphPreviewWindow_ && graphPreviewWindow_->visible() && graphPreviewSource_ == GraphPreviewSource::ImageStatistics) {
            graphPreviewDebugLog("requestGraphPreviewRefresh source=clearImageStatisticsResult");
            requestGraphPreviewRefresh();
        }

        updateContextStripUi();
    }

    void syncImageStatisticsUiToCurrentImage() {
        refreshImageStatisticsUi();
    }

    void handleImageStatisticsCenterPicked(const Vector2i& imageCoords) {
        if (!imageStatsCircleXBox_ || !imageStatsCircleYBox_) {
            return;
        }
        imageStatsCircleXBox_->set_value(std::to_string(imageCoords.x()));
        imageStatsCircleYBox_->set_value(std::to_string(imageCoords.y()));
        if (imageStatsCircleRadiusBox_ && normalizedTextBoxValue(imageStatsCircleRadiusBox_->value()).empty()) {
            imageStatsCircleRadiusBox_->set_value("15");
        }
        if (viewer_) {
            viewer_->setAiMaskPickMode(tev::ImageViewer::EAiMaskPickMode::None);
        }
        refreshImageStatisticsUi();
        setImageStatisticsStatusCaption(std::format("Circle center set to {}, {}", imageCoords.x(), imageCoords.y()));
        runImageStatistics();
    }

    void handleViewerPick(const Vector2i& imageCoords, bool positive) {
        if (activeRightPlane_ == RightPlane::ToneMapping &&
            viewer_ &&
            viewer_->aiMaskPickMode() == tev::ImageViewer::EAiMaskPickMode::ToneMappingGaze) {
            handleToneMappingGazePicked(imageCoords);
            return;
        }
        if (activeRightPlane_ == RightPlane::ImageStatistics &&
                viewer_ &&
                viewer_->aiMaskPickMode() == tev::ImageViewer::EAiMaskPickMode::StatsCenter) {
            handleImageStatisticsCenterPicked(imageCoords);
            return;
        }
        handleAiMaskPointPicked(imageCoords, positive);
    }

    void runImageStatistics() {
        if (!viewer_ || !viewer_->currentImage()) {
            clearImageStatisticsResult();
            setImageStatisticsStatusCaption("Open an image first.");
            updateGlareOverlay();
            return;
        }

        try {
            auto options = currentImageStatisticsOptions();
            auto result = native::computeImageStatistics(*viewer_->currentImage(), *viewer_->imageCanvas(), viewer_->currentReference(), options);
            imageStatsResult_ = result;
            imageStatsResultPath_ = viewer_->currentImage()->path();
            if (result.ok) {
                setImageStatisticsStatusCaption(result.statusMessage);
            } else {
                setImageStatisticsStatusCaption(result.statusMessage.empty() ? "Statistics failed." : result.statusMessage);
            }
            refreshImageStatisticsUi();
            updateGlareOverlay();
        } catch (const std::exception& e) {
            const std::string message = e.what();
            const bool luminanceMetadataMissing =
                message.find("No usable source color metadata was found") != std::string::npos;
            if (luminanceMetadataMissing && currentImageSupportsRgbStatistics()) {
                auto options = currentImageStatisticsOptions();
                options.valueMode = native::EImageStatisticsValueMode::RGB;
                try {
                    const auto result = native::computeImageStatistics(
                        *viewer_->currentImage(),
                        *viewer_->imageCanvas(),
                        viewer_->currentReference(),
                        options
                    );
                    imageStatsResult_ = result;
                    imageStatsResultPath_ = viewer_->currentImage()->path();
                    if (imageStatsValueModeCombo_) {
                        imageStatsValueModeCombo_->set_selected_index(1);
                    }
                    setImageStatisticsStatusCaption("No luminance metadata found. Showing raw RGB statistics.");
                    refreshImageStatisticsUi();
                    updateGlareOverlay();
                    return;
                } catch (...) {
                }
            }
            clearImageStatisticsResult();
            setImageStatisticsStatusCaption(std::string("Statistics failed: ") + e.what());
            updateGlareOverlay();
        }
    }

    fs::path suggestedImageStatisticsCsvPath() const {
        if (!viewer_ || !viewer_->currentImage()) {
            return {};
        }
        const fs::path imagePath = viewer_->currentImage()->path();
        const fs::path directory = imagePath.empty() ? safeCurrentPath() : imagePath.parent_path();
        const std::string stem = imagePath.empty() ? sanitizeStem("image_statistics") : sanitizeStem(imagePath);
        fs::path candidate = directory / (stem + "_stats.csv");
        int suffix = 2;
        while (fs::exists(candidate)) {
            candidate = directory / (stem + "_stats_" + std::to_string(suffix) + ".csv");
            ++suffix;
        }
        return candidate;
    }

