    void saveCropWithMergehdr(const fs::path& inputPath, const fs::path& outputPath, const tev::Box2i& crop) {
        if (paths_.mergehdr.empty() || !fs::exists(paths_.mergehdr)) {
            throw std::runtime_error("Set a valid mergehdr path in Settings.");
        }
        if (inputPath.empty()) {
            throw std::runtime_error("Current image does not have a file path.");
        }

        const auto size = crop.size();
        if (size.x() <= 0 || size.y() <= 0) {
            throw std::runtime_error("Crop must have a positive width and height.");
        }

        std::ostringstream cmd;
        cmd << shellQuote(paths_.mergehdr.string())
            << " hdrcrop -crop "
            << crop.min.x() << " "
            << crop.min.y() << " "
            << size.x() << " "
            << size.y()
            << " -o " << shellQuote(outputPath.string()) << " "
            << shellQuote(inputPath.string());

        ProcessResult result = runShellCommandWithCapturedOutput(cmd.str());
        if (result.exitCode != 0) {
            throw std::runtime_error(trim(result.stderrText.empty() ? result.stdoutText : result.stderrText));
        }
        if (!fs::exists(outputPath)) {
            throw std::runtime_error("mergehdr hdrcrop finished without writing the cropped HDR.");
        }
        rememberRecentHdr(outputPath, false, true);
    }

    void saveProjectionWithMergehdr(const fs::path& inputPath, const fs::path& outputPath,
            const std::string& fromProjection, const std::string& toProjection) {
        if (paths_.mergehdr.empty() || !fs::exists(paths_.mergehdr)) {
            throw std::runtime_error("Set a valid mergehdr path in Settings.");
        }
        if (inputPath.empty()) {
            throw std::runtime_error("Current image does not have a file path.");
        }
        if (fromProjection != "equisolid" || toProjection != "equidistant") {
            throw std::runtime_error("convertprojection currently supports equisolid -> equidistant only.");
        }

        std::ostringstream cmd;
        cmd << shellQuote(paths_.mergehdr.string())
            << " convertprojection --equisolid --equidistant"
            << " -o " << shellQuote(outputPath.string()) << " "
            << shellQuote(inputPath.string());

        ProcessResult result = runShellCommandWithCapturedOutput(cmd.str());
        if (result.exitCode != 0) {
            throw std::runtime_error(trim(result.stderrText.empty() ? result.stdoutText : result.stderrText));
        }
        if (!fs::exists(outputPath)) {
            throw std::runtime_error("mergehdr convertprojection finished without writing the projected HDR.");
        }
        rememberRecentHdr(outputPath, false, true);
    }

    void chooseInputFiles() {
        auto result = file_dialog(viewer_, FileDialogType::OpenMultiple, {}, workingDir_.string());
        if (result.empty()) {
            return;
        }

        const fs::path previousWorkingDir = workingDir_;
        inputFiles_.assign(result.begin(), result.end());
        workingDir_ = fs::path(result.front()).parent_path();
        const std::string currentOutputFolder = trim(outputFolderBox_->value());
        if (currentOutputFolder.empty() || currentOutputFolder == previousWorkingDir.string()) {
            outputFolderBox_->set_value(workingDir_.string());
        }
        if (outputNameBox_->value().empty()) {
            outputNameBox_->set_value(fs::path(result.front()).stem().string() + "_merge.hdr");
        }

        if (inputSummaryLabel_) {
            inputSummaryLabel_->set_caption(summarizeSelectedFiles(inputFiles_));
        }
    }

