    void applyProfileFromSelection(int index) {
        selectedProfileIsDualFisheye_ = false;
        blackBox_->set_value("");
        whiteBox_->set_value("");
        saturationBox_->set_value("");
        ndBox_->set_value("");
        scaleBox_->set_value("");
        rawMultipliersBox_->set_value("");
        xyzcamBox_->set_value("");
        cropBox_->set_value("");
        cropBox_->set_enabled(true);
        viewer_->setCropUi(std::nullopt);
        fisheyeBox_->set_checked(false);
        fisheyeBox_->set_enabled(true);
        rawgridBox_->set_checked(false);
        rawgridBox_->set_enabled(true);
        colorspaceCombo_->set_selected_index(0);
        demosaicCombo_->set_selected_index(0);
        mergeWeightCombo_->set_selected_index(0);
        outputFormatCombo_->set_enabled(true);

        if (index <= 0 || index > static_cast<int>(profileNames_.size())) {
            return;
        }

        fs::path profilePath = paths_.profilesDir / (profileNames_[static_cast<size_t>(index - 1)] + ".cfg");
        auto values = parseProfileFile(profilePath);
        if (values.contains("colorspace")) {
            auto items = colorspaceCombo_->items();
            auto it = std::find(items.begin(), items.end(), values["colorspace"]);
            if (it != items.end()) {
                colorspaceCombo_->set_selected_index(static_cast<int>(std::distance(items.begin(), it)));
            }
        }
        if (values.contains("demosaic")) {
            const std::string value = tev::toLower(values["demosaic"]);
            demosaicCombo_->set_selected_index(value == "dht" ? 1 : 0);
        }
        if (values.contains("merge_weight")) {
            const std::string value = tev::toLower(values["merge_weight"]);
            mergeWeightCombo_->set_selected_index(value == "linearhdr" ? 1 : 0);
        }
        setTextBoxFromProfile(blackBox_, values, "black");
        setTextBoxFromProfile(whiteBox_, values, "white");
        setTextBoxFromProfile(saturationBox_, values, "saturation");
        setTextBoxFromProfile(ndBox_, values, "nd");
        setTextBoxFromProfile(scaleBox_, values, "scale");
        setTextBoxFromProfile(rawMultipliersBox_, values, "rawmultipliers");
        setTextBoxFromProfile(xyzcamBox_, values, "xyzcam");
        if (values.contains("crop")) {
            cropBox_->set_value(values["crop"]);
            viewer_->setCropUi(parseCropString(values["crop"]));
        }
        if (values.contains("fisheye")) {
            std::string lowered = tev::toLower(values["fisheye"]);
            fisheyeBox_->set_checked(lowered == "true" || lowered == "1" || lowered == "yes");
        }
        if (values.contains("dual_fisheye")) {
            const std::string lowered = tev::toLower(values["dual_fisheye"]);
            selectedProfileIsDualFisheye_ = lowered == "true" || lowered == "1" || lowered == "yes";
        }
        if (selectedProfileIsDualFisheye_) {
            cropBox_->set_value("");
            cropBox_->set_enabled(false);
            viewer_->setCropUi(std::nullopt);
            fisheyeBox_->set_checked(false);
            fisheyeBox_->set_enabled(false);
            rawgridBox_->set_checked(false);
            rawgridBox_->set_enabled(false);
            outputFormatCombo_->set_selected_index(0);
            outputFormatCombo_->set_enabled(false);
        }
    }

    std::string selectedProfileName() const {
        int index = profileCombo_->selected_index();
        if (index <= 0 || index > static_cast<int>(profileNames_.size())) {
            return {};
        }
        return profileNames_[static_cast<size_t>(index - 1)];
    }

    std::string selectedColorspace() const {
        return colorspaceCombo_->items()[static_cast<size_t>(colorspaceCombo_->selected_index())];
    }

    std::string selectedDemosaic() const {
        return demosaicCombo_->selected_index() == 0 ? "ahd" : "dht";
    }

    std::string selectedMergeWeight() const {
        return mergeWeightCombo_->selected_index() == 0 ? "hdrmerge" : "linearhdr";
    }

    std::string selectedOutputFormat() const {
        return outputFormatCombo_->selected_index() == 0 ? "hdr" : "exr";
    }

    void startMerge() {
        if (mergeJob_.active) {
            showMessage("A merge is already running.");
            return;
        }
        if (paths_.mergehdr.empty() || !fs::exists(paths_.mergehdr)) {
            showMessage("Set a valid mergehdr path in Settings.");
            return;
        }
        if (inputFiles_.empty()) {
            showMessage("Choose RAW files first.");
            return;
        }

        for (const auto& file : inputFiles_) {
            if (!fs::exists(file)) {
                showMessage("A selected RAW file no longer exists:\n" + file + "\n\nChoose input files again.");
                return;
            }
        }

        workingDir_ = fs::path(inputFiles_.front()).parent_path();

        const bool dualFisheye = selectedProfileIsDualFisheye_;
        std::string crop;
        if (!dualFisheye) {
            crop = normalizedTextBoxValue(cropBox_->value());
            if (crop.empty()) {
                crop = currentViewerCropString();
                if (!crop.empty()) {
                    cropBox_->set_value(crop);
                }
            }
        }
        if (fisheyeBox_->checked() && crop.empty()) {
            showMessage("Fisheye correction needs a crop first.");
            return;
        }

        std::string outputName = normalizedTextBoxValue(outputNameBox_->value());
        if (outputName.empty()) {
            outputName = inputFiles_.empty() ? "mergehdr_output" : fs::path(inputFiles_.front()).stem().string() + "_merge";
        }

        fs::path outputDir = outputFolderBox_->value().empty() ? workingDir_ : fs::path(outputFolderBox_->value());
        if (!outputDir.is_absolute()) {
            outputDir = fs::absolute(workingDir_ / outputDir);
        }
        fs::create_directories(outputDir);

        std::string outputFormat = dualFisheye ? "hdr" : selectedOutputFormat();
        if (fs::path(outputName).extension().empty()) {
            outputName += "." + outputFormat;
        }
        if (dualFisheye) {
            fs::path normalizedOutputName(outputName);
            normalizedOutputName.replace_extension(".hdr");
            outputName = normalizedOutputName.string();
            outputNameBox_->set_value(outputName);
        }
        fs::path finalOutput = outputDir / outputName;
        fs::path primaryOutput = finalOutput;
        fs::path secondaryOutput;
        if (dualFisheye) {
            const std::string stem = finalOutput.has_extension()
                ? finalOutput.stem().string()
                : finalOutput.filename().string();
            primaryOutput = finalOutput.parent_path() / (stem + "_left.hdr");
            secondaryOutput = finalOutput.parent_path() / (stem + "_right.hdr");
        }
        fs::path tempHdr = paths_.cacheDir / (sanitizeStem(finalOutput) + "_render.hdr");
        fs::path jobLog = paths_.cacheDir / (sanitizeStem(finalOutput) + "_merge.log");
        const bool requiresNativeExrConversion = !dualFisheye && outputFormat == "exr";

        std::ostringstream cmd;
        cmd << "cd " << shellQuote(workingDir_.string()) << " && ";
        cmd << shellQuote(paths_.mergehdr.string()) << " ";
        const std::string profile = selectedProfileName();
        if (!profile.empty()) {
            cmd << "-profile " << shellQuote(profile) << " ";
        }
        cmd << "run ";
        cmd << "--colorspace " << shellQuote(selectedColorspace()) << " ";
        if (!normalizedTextBoxValue(blackBox_->value()).empty()) cmd << "--black " << shellQuote(normalizedTextBoxValue(blackBox_->value())) << " ";
        if (!normalizedTextBoxValue(whiteBox_->value()).empty()) cmd << "--white " << shellQuote(normalizedTextBoxValue(whiteBox_->value())) << " ";
        if (!normalizedTextBoxValue(saturationBox_->value()).empty()) cmd << "--saturation " << shellQuote(normalizedTextBoxValue(saturationBox_->value())) << " ";
        if (!normalizedTextBoxValue(ndBox_->value()).empty()) cmd << "--nd " << shellQuote(normalizedTextBoxValue(ndBox_->value())) << " ";
        if (!normalizedTextBoxValue(scaleBox_->value()).empty()) cmd << "--scale " << shellQuote(normalizedTextBoxValue(scaleBox_->value())) << " ";
        if (!normalizedTextBoxValue(rawMultipliersBox_->value()).empty()) cmd << "--rawmultipliers " << shellQuote(normalizedTextBoxValue(rawMultipliersBox_->value())) << " ";
        if (!normalizedTextBoxValue(xyzcamBox_->value()).empty()) cmd << "--xyzcam " << shellQuote(normalizedTextBoxValue(xyzcamBox_->value())) << " ";
        if (!crop.empty()) cmd << "--crop " << crop << " ";
        cmd << "--demosaic " << selectedDemosaic() << " ";
        cmd << "--merge-weight " << selectedMergeWeight() << " ";
        if (rawgridBox_->checked()) cmd << "--rawgrid ";
        if (bloomPreventBox_->checked()) cmd << "--bloom-prevent ";
        cmd << (fisheyeBox_->checked() ? "--fisheye " : "--no-fisheye ");
        if (!normalizedTextBoxValue(extraArgsBox_->value()).empty()) {
            cmd << normalizedTextBoxValue(extraArgsBox_->value()) << " ";
        }
        cmd << "-o " << shellQuote((requiresNativeExrConversion ? tempHdr : finalOutput).string()) << " ";
        cmd << quoteInputFiles(inputFiles_);

        mergeJob_.active = true;
        mergeJob_.logPath = jobLog;
        mergeJob_.outputPath = primaryOutput;
        mergeJob_.secondaryOutputPath = secondaryOutput;
        mergeJob_.command = cmd.str();
        mergeJob_.token = ++mergeToken_;
        mergeJob_.previousWriteTime = fs::exists(primaryOutput) ? std::optional<fs::file_time_type>{fs::last_write_time(primaryOutput)} : std::nullopt;
        mergeJob_.secondaryPreviousWriteTime = !secondaryOutput.empty() && fs::exists(secondaryOutput)
            ? std::optional<fs::file_time_type>{fs::last_write_time(secondaryOutput)}
            : std::nullopt;
        mergeJob_.pid = spawnShellJob(cmd.str(), jobLog);
        lastMergeCommand_ = cmd.str();
        stageLabel_->set_caption("Running merge");
        rangeLabel_->set_caption("Waiting for luminance summary...");
        issuesLabel_->set_caption("");
        progressBar_->set_value(0.02f);

        const uint64_t token = mergeJob_.token;
        const pid_t pid = mergeJob_.pid;
        const fs::path logPath = mergeJob_.logPath;
        const fs::path outputPath = mergeJob_.outputPath;
        const fs::path secondaryOutputPath = mergeJob_.secondaryOutputPath;
        const fs::path intermediateHdrPath = tempHdr;
        const bool outputUsesRadiance = selectedColorspace() == "rad" && outputFormat == "hdr";
        const auto previousWriteTime = mergeJob_.previousWriteTime;
        const auto secondaryPreviousWriteTime = mergeJob_.secondaryPreviousWriteTime;

        std::thread([this, token, pid, logPath, outputPath, secondaryOutputPath, intermediateHdrPath,
                     requiresNativeExrConversion, outputUsesRadiance, previousWriteTime,
                     secondaryPreviousWriteTime, dualFisheye]() {
            while (!tev::shuttingDown()) {
                int status = 0;
                pid_t result = waitpid(pid, &status, WNOHANG);
                const bool finished = result == pid;
                int exitCode = finished ? (WIFEXITED(status) ? WEXITSTATUS(status) : status) : -1;
                std::string log = readFile(logPath);
                int percent = lastPercentInText(log);
                if (finished && exitCode == 0) {
                    percent = 100;
                }
                if (percent < 0) {
                    percent = finished ? 100 : 5;
                }
                const std::string stage = lastStageInText(log);
                const std::string range = summarizeRangeFromLog(log);
                std::string issues = collectWarnings(log);
                if (finished && exitCode == 0 && requiresNativeExrConversion) {
                    try {
                        convertHdrToExrNative(intermediateHdrPath, outputPath);
                        std::error_code removeError;
                        fs::remove(intermediateHdrPath, removeError);
                    } catch (const std::exception& e) {
                        exitCode = 1;
                        if (!issues.empty()) {
                            issues += "\n";
                        }
                        issues += std::string("Native EXR conversion failed: ") + e.what();
                    }
                }

                viewer_->scheduleToUiThread([this, token, percent, stage, range, issues, finished, exitCode,
                                             outputPath, secondaryOutputPath, outputUsesRadiance,
                                             previousWriteTime, secondaryPreviousWriteTime, dualFisheye]() {
                    if (token != mergeJob_.token) {
                        return;
                    }

                    progressBar_->set_value(std::clamp(percent / 100.0f, 0.0f, 1.0f));
                    stageLabel_->set_caption(stage.empty() ? (finished ? "Finished" : "Merging") : stage);
                    rangeLabel_->set_caption(range);
                    issuesLabel_->set_caption(issues);

                    if (!finished) {
                        return;
                    }

                    mergeJob_.active = false;
                    const bool outputExists = fs::exists(outputPath);
                    const bool secondaryOutputExists = !dualFisheye || fs::exists(secondaryOutputPath);
                    bool outputUpdated = outputExists;
                    if (outputExists && previousWriteTime.has_value()) {
                        outputUpdated = fs::last_write_time(outputPath) != *previousWriteTime;
                    }
                    bool secondaryOutputUpdated = secondaryOutputExists;
                    if (dualFisheye && secondaryOutputExists && secondaryPreviousWriteTime.has_value()) {
                        secondaryOutputUpdated = fs::last_write_time(secondaryOutputPath) != *secondaryPreviousWriteTime;
                    }

                    if (exitCode == 0 && outputExists && secondaryOutputExists) {
                        stageLabel_->set_caption(dualFisheye ? "Dual-fisheye merge complete" : "Merge complete");
                        if (!outputUpdated || !secondaryOutputUpdated) {
                            issuesLabel_->set_caption(dualFisheye
                                ? "One or both output paths already existed and were not updated during this run."
                                : "Output path already existed and was not updated during this run.");
                        }
                        if (dualFisheye) {
                            // Load right first so the left (primary) view remains current.
                            loadImageIntoViewer(secondaryOutputPath);
                        }
                        loadImageIntoViewer(outputPath);
                        setRadiance179Boost(outputUsesRadiance);
                    } else {
                        stageLabel_->set_caption("Merge failed");
                        if (exitCode == 0 && dualFisheye && (!outputExists || !secondaryOutputExists)) {
                            std::string missing = "The dual-fisheye merge did not create both expected outputs:";
                            if (!outputExists) {
                                missing += "\n" + outputPath.string();
                            }
                            if (!secondaryOutputExists) {
                                missing += "\n" + secondaryOutputPath.string();
                            }
                            issuesLabel_->set_caption(missing);
                        } else if (issues.empty()) {
                            issuesLabel_->set_caption("Check merge settings.");
                        }
                    }
                });

                if (finished) {
                    break;
                }
                std::this_thread::sleep_for(80ms);
            }
        }).detach();
    }

    template <typename Builder, typename Finish>
    void startWorkerTask(WorkerTask& task, Builder&& builder, Finish&& finish) {
        {
            std::lock_guard<std::mutex> lock{task.mutex};
            if (task.active) {
                showMessage("A task is already running in this tab.");
                return;
            }
        }

        const auto [command, error] = builder();
        if (!error.empty()) {
            showMessage(error);
            return;
        }

        {
            std::lock_guard<std::mutex> lock{task.mutex};
            task.active = true;
        }

        std::thread([this, &task, command, finish = std::forward<Finish>(finish)]() mutable {
            ProcessResult result = runShellCommandWithCapturedOutput(command);
            viewer_->scheduleToUiThread([&task, result = std::move(result), finish = std::move(finish)]() mutable {
                {
                    std::lock_guard<std::mutex> lock{task.mutex};
                    task.active = false;
                }
                finish(std::move(result));
            });
        }).detach();
    }

    template <typename Work, typename Finish>
    void startWorkerResultTask(WorkerTask& task, Work&& work, Finish&& finish) {
        {
            std::lock_guard<std::mutex> lock{task.mutex};
            if (task.active) {
                showMessage("A task is already running in this tab.");
                return;
            }
            task.active = true;
        }

        std::thread([this, &task, work = std::forward<Work>(work), finish = std::forward<Finish>(finish)]() mutable {
            ProcessResult result = work();
            viewer_->scheduleToUiThread([&task, result = std::move(result), finish = std::move(finish)]() mutable {
                {
                    std::lock_guard<std::mutex> lock{task.mutex};
                    task.active = false;
                }
                finish(std::move(result));
            });
        }).detach();
    }

    static ProcessResult calculateReferenceChartXyz(
        const fs::path& imagePath,
        const fs::path& cellsPath,
        const std::string& fallbackSpace
    ) {
        ProcessResult result;
        try {
            struct CellRect {
                int x = 0;
                int y = 0;
                int w = 0;
                int h = 0;
            };

            std::ifstream cellsInput(cellsPath);
            if (!cellsInput) {
                throw std::runtime_error("Could not open reference cells: " + cellsPath.string());
            }

            std::vector<CellRect> cells;
            std::string line;
            while (std::getline(cellsInput, line)) {
                line = trim(line);
                if (line.empty() || line.front() == '#') {
                    continue;
                }
                std::istringstream stream(line);
                CellRect cell;
                if (!(stream >> cell.x >> cell.y >> cell.w >> cell.h) || cell.w <= 0 || cell.h <= 0) {
                    throw std::runtime_error("Invalid reference cell row: " + line);
                }
                cells.push_back(cell);
            }
            if (cells.size() != 24) {
                throw std::runtime_error(
                    "A1-D6 output requires exactly 24 reference cells; found " +
                    std::to_string(cells.size()) + "."
                );
            }

            const CellRect detectedWhite = cells.front();
            std::sort(cells.begin(), cells.end(), [](const CellRect& lhs, const CellRect& rhs) {
                if (lhs.y != rhs.y) {
                    return lhs.y > rhs.y;
                }
                return lhs.x < rhs.x;
            });
            for (size_t row = 0; row < 4; ++row) {
                auto begin = cells.begin() + static_cast<std::ptrdiff_t>(row * 6);
                std::sort(begin, begin + 6, [](const CellRect& lhs, const CellRect& rhs) {
                    return lhs.x < rhs.x;
                });
            }

            const HdrImage image = readRadianceHDR(imagePath.string());
            for (const CellRect& cell : cells) {
                if (cell.x < 0 || cell.y < 0 || cell.w <= 0 || cell.h <= 0 ||
                    static_cast<size_t>(cell.x + cell.w) > image.width ||
                    static_cast<size_t>(cell.y + cell.h) > image.height) {
                    throw std::runtime_error("A reference cell falls outside the HDR image bounds.");
                }
            }

            BlurSourceColorInfo colorInfo;
            const auto setIdentity = [&colorInfo](const std::string& description) {
                colorInfo.valid = true;
                colorInfo.xyzIdentity = true;
                colorInfo.sourceToXyz = BlurMat3{};
                colorInfo.sourceToXyz.m[0][0] = 1.0;
                colorInfo.sourceToXyz.m[1][1] = 1.0;
                colorInfo.sourceToXyz.m[2][2] = 1.0;
                colorInfo.description = description;
            };
            const auto primariesAreXyzIdentity = [](const std::array<double, 8>& values) {
                return
                    std::abs(values[0] - 1.0) < 1e-6 && std::abs(values[1]) < 1e-6 &&
                    std::abs(values[2]) < 1e-6 && std::abs(values[3] - 1.0) < 1e-6 &&
                    std::abs(values[4]) < 1e-6 && std::abs(values[5]) < 1e-6;
            };

            const auto formatIt = image.header.find("FORMAT");
            if (formatIt != image.header.end() &&
                createViewLower(formatIt->second).find("xyze") != std::string::npos) {
                setIdentity("Radiance XYZE header");
            }

            if (!colorInfo.valid) {
                std::array<double, 8> primaries{};
                const bool targetPrimaries = blurParseTargetPrimariesAndWhite(image, primaries);
                const bool radiancePrimaries = !targetPrimaries && blurParseRadiancePrimaries(image, primaries);
                if (targetPrimaries || radiancePrimaries) {
                    if (primariesAreXyzIdentity(primaries)) {
                        setIdentity(targetPrimaries
                            ? "TargetPrimaries/TargetWhitePoint (XYZ identity)"
                            : "Radiance PRIMARIES (XYZ identity)");
                    } else if (blurPrimariesToXyzMatrix(primaries, colorInfo.sourceToXyz)) {
                        colorInfo.valid = true;
                        colorInfo.description = targetPrimaries
                            ? "TargetPrimaries/TargetWhitePoint header"
                            : "Radiance PRIMARIES header";
                    }
                }
            }

            if (!colorInfo.valid) {
                BlurMat3 sensorToXyz{};
                if (blurParseHeaderMatrix3x3(image, "SENSOR2XYZ", sensorToXyz)) {
                    colorInfo.valid = true;
                    colorInfo.sourceToXyz = sensorToXyz;
                    colorInfo.description = "SENSOR2XYZ header";
                } else if (blurParseSensorToXyz(image, sensorToXyz)) {
                    colorInfo.valid = true;
                    colorInfo.sourceToXyz = sensorToXyz;
                    colorInfo.description = "XYZCAM header";
                }
            }

            if (!colorInfo.valid) {
                const std::string space = tev::toLower(trim(fallbackSpace));
                if (space == "xyz") {
                    setIdentity("Reference space fallback: xyz");
                } else if (space == "rad") {
                    colorInfo.valid = true;
                    colorInfo.sourceToXyz = blurRadianceRgbToXyzMatrix();
                    colorInfo.description = "Reference space fallback: Radiance RGB";
                } else if (space == "srgb") {
                    const std::array<double, 8> srgb{
                        0.6400, 0.3300,
                        0.3000, 0.6000,
                        0.1500, 0.0600,
                        0.3127, 0.3290,
                    };
                    if (!blurPrimariesToXyzMatrix(srgb, colorInfo.sourceToXyz)) {
                        throw std::runtime_error("Could not construct the sRGB-to-XYZ matrix.");
                    }
                    colorInfo.valid = true;
                    colorInfo.description = "Reference space fallback: linear sRGB";
                } else {
                    throw std::runtime_error(
                        "Raw reference HDR needs SENSOR2XYZ/XYZCAM metadata. "
                        "Choose rad, srgb, or xyz only if that is the actual reference space."
                    );
                }
            }

            int detectedWhiteIndex = -1;
            std::ostringstream output;
            output << "Reference chart XYZ (A-D top-to-bottom, 1-6 left-to-right)\n";
            output << "Color transform: " << colorInfo.description << "\n";
            output << "Sample scale: HDR values x 179\n\n";
            output << std::left << std::setw(6) << "Cell"
                   << std::right << std::setw(16) << "X"
                   << std::setw(16) << "Y"
                   << std::setw(16) << "Z" << "\n";
            output << std::string(54, '-') << "\n";

            for (size_t index = 0; index < cells.size(); ++index) {
                const CellRect& cell = cells[index];
                std::array<double, 3> source{0.0, 0.0, 0.0};
                for (int y = cell.y; y < cell.y + cell.h; ++y) {
                    for (int x = cell.x; x < cell.x + cell.w; ++x) {
                        const size_t pixel =
                            (static_cast<size_t>(y) * image.width + static_cast<size_t>(x)) * 3;
                        source[0] += static_cast<double>(image.rgb[pixel + 0]);
                        source[1] += static_cast<double>(image.rgb[pixel + 1]);
                        source[2] += static_cast<double>(image.rgb[pixel + 2]);
                    }
                }
                const double sampleScale = 179.0 / static_cast<double>(cell.w * cell.h);
                for (double& value : source) {
                    value *= sampleScale;
                }
                const std::array<double, 3> xyz = blurMat3MulVec(colorInfo.sourceToXyz, source);
                const char rowLabel = static_cast<char>('A' + index / 6);
                const int columnLabel = static_cast<int>(index % 6) + 1;
                std::string cellLabel;
                cellLabel.push_back(rowLabel);
                cellLabel += std::to_string(columnLabel);

                if (cell.x == detectedWhite.x && cell.y == detectedWhite.y &&
                    cell.w == detectedWhite.w && cell.h == detectedWhite.h) {
                    detectedWhiteIndex = static_cast<int>(index);
                }

                output << std::left << std::setw(6) << cellLabel
                       << std::right << std::fixed << std::setprecision(6)
                       << std::setw(16) << xyz[0]
                       << std::setw(16) << xyz[1]
                       << std::setw(16) << xyz[2] << "\n";
            }

            if (detectedWhiteIndex >= 0) {
                output << "\nAuto-detected white: "
                       << static_cast<char>('A' + detectedWhiteIndex / 6)
                       << (detectedWhiteIndex % 6 + 1) << "\n";
            }

            result.exitCode = 0;
            result.stdoutText = output.str();
        } catch (const std::exception& error) {
            result.exitCode = 1;
            result.stderrText = std::string("Reference XYZ failed: ") + error.what();
        }
        return result;
    }

    void showReferenceChartXyz() {
        if (trim(refFileBox_->value()).empty()) {
            showMessage("Choose a reference HDR first.");
            return;
        }
        if (trim(refCellsBox_->value()).empty()) {
            showMessage("Run Auto cells ref first.");
            return;
        }

        fs::path imagePath = trim(refFileBox_->value());
        fs::path cellsPath = trim(refCellsBox_->value());
        if (imagePath.is_relative()) {
            imagePath = workingDir_ / imagePath;
        }
        if (cellsPath.is_relative()) {
            cellsPath = workingDir_ / cellsPath;
        }
        const std::string fallbackSpace =
            refColorCombo_->items()[static_cast<size_t>(refColorCombo_->selected_index())];

        setColorResultText("Calculating reference XYZ values...");
        startWorkerResultTask(
            colorTask_,
            [imagePath, cellsPath, fallbackSpace] {
                return calculateReferenceChartXyz(imagePath, cellsPath, fallbackSpace);
            },
            [this](ProcessResult result) {
                const std::string text = result.exitCode == 0
                    ? result.stdoutText
                    : result.stderrText;
                setColorResultText(text);
                if (result.exitCode != 0) {
                    showMessage(text);
                }
            }
        );
    }

    std::pair<std::string, std::string> buildColorCommand() const {
        if (paths_.mergehdr.empty() || !fs::exists(paths_.mergehdr)) {
            return {"", "Set a valid mergehdr path in Settings."};
        }
        if (trim(refFileBox_->value()).empty() || trim(testFileBox_->value()).empty()) {
            return {"", "Choose both reference and camera HDR files first."};
        }

        std::ostringstream cmd;
        cmd << "cd " << shellQuote(workingDir_.string()) << " && ";
        cmd << shellQuote(paths_.mergehdr.string()) << " colorcalibrate ";
        cmd << shellQuote(refFileBox_->value()) << " " << shellQuote(testFileBox_->value()) << " ";
        if (!trim(refCellsBox_->value()).empty()) cmd << "-rc " << shellQuote(refCellsBox_->value()) << " ";
        if (!trim(testCellsBox_->value()).empty()) cmd << "-tc " << shellQuote(testCellsBox_->value()) << " ";
        cmd << "-refcol " << shellQuote(refColorCombo_->items()[static_cast<size_t>(refColorCombo_->selected_index())]) << " ";
        cmd << "-minimizer " << shellQuote(minimizerCombo_->items()[static_cast<size_t>(minimizerCombo_->selected_index())]) << " ";
        if (!trim(colorXyzcamBox_->value()).empty()) cmd << "-xyzcam " << shellQuote(trim(colorXyzcamBox_->value())) << " ";
        return {cmd.str(), {}};
    }

    void setColorResultText(std::string_view text) {
        if (!colorResultArea_) {
            return;
        }
        colorResultArea_->setText(text);
        if (colorResultScroll_ && viewer_) {
            colorResultScroll_->perform_layout(viewer_->nvg_context());
            syncColorResultHorizontalControls();
            viewer_->redraw();
        }
    }

    void syncColorResultHorizontalControls() {
        if (!colorResultHorizontalSlider_ || !colorResultScroll_) {
            return;
        }
        colorResultHorizontalSlider_->set_enabled(colorResultScroll_->hasHorizontalOverflow());
        colorResultHorizontalSlider_->set_value(colorResultScroll_->horizontalScroll());
    }

    void startColorCalibration() {
        setColorResultText("Running color calibration...");
        startWorkerTask(colorTask_, [this] { return buildColorCommand(); }, [this](ProcessResult result) {
            setColorResultText(result.stdoutText + result.stderrText);
        });
    }

    void copyRecommendedMatrix() {
        auto matrix = parseRecommendedMatrix(colorResultArea_->text());
        if (!matrix.has_value()) {
            showMessage("No recommended xyzcam found yet.");
            return;
        }

        std::ostringstream oss;
        for (size_t i = 0; i < matrix->size(); ++i) {
            if (i) oss << ' ';
            oss << std::fixed << std::setprecision(6) << (*matrix)[i];
        }
        glfwSetClipboardString(viewer_->glfw_window(), oss.str().c_str());
        showMessage("Copied recommended xyzcam.");
    }

    void runChartCells(bool reference) {
        if (paths_.mergehdr.empty() || !fs::exists(paths_.mergehdr)) {
            showMessage("Set a valid mergehdr path in Settings.");
            return;
        }

        const std::string imagePath = reference ? trim(refFileBox_->value()) : trim(testFileBox_->value());
        if (imagePath.empty()) {
            showMessage("Choose an HDR image first.");
            return;
        }

        fs::path image = imagePath;
        fs::path cells = paths_.cacheDir / (sanitizeStem(image) + (reference ? "_ref_cells.txt" : "_test_cells.txt"));
        fs::path preview = paths_.cacheDir / (sanitizeStem(image) + (reference ? "_ref_cells.jpg" : "_test_cells.jpg"));

        std::ostringstream cmd;
        cmd << "cd " << shellQuote(image.parent_path().string()) << " && ";
        cmd << shellQuote(paths_.mergehdr.string()) << " chartcells "
            << shellQuote(image.string()) << " -o " << shellQuote(cells.string())
            << " -preview " << shellQuote(preview.string()) << " --white-first";

        startWorkerTask(reference ? colorTask_ : shutterTask_, [cmd = cmd.str()]() { return std::pair<std::string, std::string>{cmd, {}}; },
            [this, reference, cells, preview](ProcessResult result) {
                if (result.exitCode != 0) {
                    showMessage("chartcells failed:\n" + result.stdoutText + result.stderrText);
                    return;
                }
                if (reference) {
                    refCellsBox_->set_value(cells.string());
                } else {
                    testCellsBox_->set_value(cells.string());
                }
                if (fs::exists(preview)) {
                    loadImageIntoViewer(preview);
                }
            });
    }

    std::pair<std::string, std::string> buildShutterCommand() const {
        if (paths_.mergehdr.empty() || !fs::exists(paths_.mergehdr)) {
            return {"", "Set a valid mergehdr path in Settings."};
        }
        const auto sequences = splitLines(shutterSequencesArea_->text());
        if (sequences.empty()) {
            return {"", "Add at least one shutter sequence first."};
        }

        std::ostringstream cmd;
        cmd << "cd " << shellQuote(workingDir_.string()) << " && ";
        const std::string profile = selectedProfileName();
        cmd << shellQuote(paths_.mergehdr.string()) << " ";
        if (!profile.empty()) cmd << "-profile " << shellQuote(profile) << " ";
        cmd << "shutter ";
        for (const auto& seq : sequences) cmd << "-seq " << shellQuote(seq) << " ";
        for (const auto& crop : splitLines(shutterCropsArea_->text())) cmd << "-crop " << shellQuote(crop) << " ";
        cmd << "-channel " << shellQuote(shutterChannelCombo_->items()[static_cast<size_t>(shutterChannelCombo_->selected_index())]);
        return {cmd.str(), {}};
    }

    void startShutterCalibration() {
        shutterResultArea_->setText("Running shutter calibration...");
        startWorkerTask(shutterTask_, [this] { return buildShutterCommand(); }, [this](ProcessResult result) {
            shutterResultArea_->setText(result.stdoutText + result.stderrText);
        });
    }

    std::pair<std::string, std::string> buildApertureCommand() const {
        if (paths_.mergehdr.empty() || !fs::exists(paths_.mergehdr)) {
            return {"", "Set a valid mergehdr path in Settings."};
        }
        const auto sequences = splitLines(apertureSequencesArea_->text());
        if (sequences.empty()) {
            return {"", "Add at least one aperture sequence first."};
        }
        if (trim(apertureCropBox_->value()).empty()) {
            return {"", "Set a crop for aperture calibration first."};
        }

        std::ostringstream cmd;
        cmd << "cd " << shellQuote(workingDir_.string()) << " && ";
        const std::string profile = selectedProfileName();
        cmd << shellQuote(paths_.mergehdr.string()) << " ";
        if (!profile.empty()) cmd << "-profile " << shellQuote(profile) << " ";
        cmd << "aperture ";
        if (!trim(apertureShuttercBox_->value()).empty()) {
            cmd << "-shutterc " << shellQuote(trim(apertureShuttercBox_->value())) << " ";
        }
        cmd << "-crop " << shellQuote(trim(apertureCropBox_->value())) << " ";
        for (const auto& seq : sequences) cmd << "-seq " << shellQuote(seq) << " ";
        return {cmd.str(), {}};
    }

    void startApertureCalibration() {
        apertureResultArea_->setText("Running aperture calibration...");
        startWorkerTask(apertureTask_, [this] { return buildApertureCommand(); }, [this](ProcessResult result) {
            apertureResultArea_->setText(result.stdoutText + result.stderrText);
        });
    }

